const $=s=>document.querySelector(s), app=$("#app");
const uuid=()=>{try{if(globalThis.crypto?.randomUUID)return crypto.randomUUID()}catch{}return "d_"+Date.now().toString(36)+"_"+Math.random().toString(36).slice(2)+"_"+Math.random().toString(36).slice(2)};
