try{token=localStorage.getItem('sico_token')}catch{}
try{device=localStorage.getItem('sico_device')}catch{}
try{adminToken=localStorage.getItem('sico_admin_token')}catch{}
if(!device){device=uuid();try{localStorage.setItem('sico_device',device)}catch{}}
let authScreenMode=null,authBusy=false,booting=true;
let renderSeq=0;
const currentSeq=()=>renderSeq;
let audioCtx=null,lastUiSound=0,lastGameSound="",chatSendUntil=0,chatTimer=null;
let soundEnabled=true,hapticsEnabled=true;
try{soundEnabled=localStorage.getItem('sico_sound')!=='0';hapticsEnabled=localStorage.getItem('sico_haptics')!=='0'}catch{}
const sicoHapticPatterns={click:7,tab:9,bet:[10,16],win:[12,22,12],lose:[28,16],spin:[5,8,5],crash:[28,45,65],reveal:[9,14],cashout:[12,20],levelup:[14,24,14],success:[10,18],error:[30],notify:10,plinko:[6,9,6],miss:[30,20]};
function sicoHaptic(kind="click"){try{if(!hapticsEnabled||!navigator.vibrate)return;navigator.vibrate(sicoHapticPatterns[kind]??7)}catch{}}
function sicoTone(ctx,kind,when=0){const t=ctx.currentTime+when;const osc=(type,freq,vol,dur,end,attack=.006)=>{const o=ctx.createOscillator(),g=ctx.createGain(),f=ctx.createBiquadFilter();o.type=type;o.frequency.setValueAtTime(freq,t);if(end)o.frequency.exponentialRampToValueAtTime(end,t+dur);f.type='lowpass';f.frequency.setValueAtTime(Math.min(5200,Math.max(900,freq*4.5)),t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+attack);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(f).connect(g).connect(ctx.destination);o.start(t);o.stop(t+dur+.02)};
if(kind==='click')osc('sine',720,.016,.045,820);
else if(kind==='tab'){osc('sine',520,.012,.055,760);osc('sine',980,.009,.045,1160,.012)}
else if(kind==='bet'){osc('triangle',180,.018,.09,260);osc('sine',520,.012,.08,700,.025)}
else if(kind==='win'){osc('sine',520,.018,.11,720);osc('sine',780,.019,.13,1040,.07);osc('sine',1040,.021,.18,1480,.14)}
else if(kind==='lose'){osc('triangle',260,.02,.16,135);osc('sine',170,.012,.2,95,.03)}
else if(kind==='reveal'){osc('sine',430,.014,.055,680);osc('sine',680,.011,.075,920,.035)}
else if(kind==='cashout'){osc('sine',620,.017,.08,820);osc('sine',920,.017,.12,1280,.055)}
else if(kind==='levelup'){osc('sine',440,.014,.09,620);osc('sine',620,.017,.10,900,.07);osc('sine',900,.021,.17,1500,.13)}
else if(kind==='success'){osc('sine',560,.015,.07,780);osc('sine',840,.014,.11,1120,.05)}
else if(kind==='error'){osc('square',170,.012,.11,115)}
else if(kind==='notify')osc('sine',740,.012,.065,980)
else if(kind==='spin')osc('triangle',150,.009,.04,205)
else if(kind==='plinko'){osc('sine',210,.008,.045,250);osc('sine',330,.007,.045,390,.02)}
else if(kind==='miss'){osc('triangle',220,.015,.18,120);osc('sine',120,.008,.22,80,.03)}}
function sicoNoise(ctx,when=0,dur=.12,vol=.016,low=900){const len=Math.max(1,Math.floor(ctx.sampleRate*dur)),buf=ctx.createBuffer(1,len,ctx.sampleRate),data=buf.getChannelData(0);for(let i=0;i<len;i++){const x=i/len;data[i]=(Math.random()*2-1)*Math.pow(1-x,2.8)}const src=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain(),t=ctx.currentTime+when;src.buffer=buf;f.type='bandpass';f.frequency.setValueAtTime(low,t);f.frequency.exponentialRampToValueAtTime(Math.max(120,low*.4),t+dur);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.004);g.gain.exponentialRampToValueAtTime(.0001,t+dur);src.connect(f).connect(g).connect(ctx.destination);src.start(t);src.stop(t+dur+.01)}
function sicoSound(kind='click'){try{const now=performance.now();if(kind==='click'&&now-lastUiSound<55)return;lastUiSound=now;const h=['win','levelup','crash','lose','bet','cashout','reveal','tab','click','plinko','miss'].includes(kind);if(h)sicoHaptic(kind);if(!soundEnabled)return;audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();if(kind==='crash'){sicoNoise(audioCtx,0,.2,.035,700);sicoTone(audioCtx,'lose',.015);return}if(kind==='spin'){sicoTone(audioCtx,'spin');return}if(kind==='plinko'){sicoTone(audioCtx,'plinko');return}sicoTone(audioCtx,kind)}catch{}}
function sicoSoundSettings(sound,haptics){soundEnabled=!!sound;hapticsEnabled=!!haptics;try{localStorage.setItem('sico_sound',soundEnabled?'1':'0');localStorage.setItem('sico_haptics',hapticsEnabled?'1':'0')}catch{}}
const api=async(url,opt={})=>{const method=String(opt.method||'GET').toUpperCase(),providedHeaders=opt.headers||{},h={...providedHeaders,'X-Device-ID':device,...(token?{Authorization:'Bearer '+token}:{}),...(providedHeaders.Authorization?{Authorization:providedHeaders.Authorization}:{}),...(method!=='GET'&&method!=='HEAD'&&!Object.keys(providedHeaders).some(k=>k.toLowerCase()==='x-request-id')?{'X-Request-ID':rid()}: {})};let r;try{r=await fetch(url,{...opt,headers:h,signal:opt.signal||globalThis.AbortSignal?.timeout?.(20000)})}catch(e){throw Object.assign(Error(e?.name==='TimeoutError'?'Сервер отвечает слишком долго. Проверь соединение.':'Не удалось связаться с сервером'),{status:0,cause:e})}let d={};try{d=await r.json()}catch{}if(!r.ok)throw Object.assign(Error(d.error||`Ошибка ${r.status}`),{status:r.status});return d};
const rid=()=>uuid();
function toast(t){const x=document.createElement('div');x.className='toast';x.textContent=t;document.body.append(x);setTimeout(()=>x.remove(),2600)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function avatar(u,cls='avatar'){const ai=u?.equipped?.avatar&&typeof u.equipped.avatar==='object'?u.equipped.avatar:null;const itemIcon=ai?.icon||'';const frame=u?.equipped?.frame&&typeof u.equipped.frame==='object'?u.equipped.frame.value:'';const fx=u?.equipped?.effect&&typeof u.equipped.effect==='object'?u.equipped.effect.value:'';if(ai?.icon)return `<div class="${cls} frame-${esc(frame||'none')} effect-${esc(fx||'none')}">${esc(ai.icon)}</div>`;if(u?.avatar&&typeof u.avatar==='string')return `<img class="${cls} frame-${esc(frame||'none')} effect-${esc(fx||'none')}" src="${u.avatar}">`;return `<div class="${cls} frame-${esc(frame||'none')} effect-${esc(fx||'none')}">${itemIcon||esc((u?.login||'?')[0]).toUpperCase()}</div>`}
function authView(mode='login',preserve=false,data={}){
  if(token&&me){booting=false;return render(route||'home')}
  authScreenMode=mode;booting=false;
  const oldLogin=preserve?$('#login')?.value||'':(data.login||'');
  const oldPass=preserve?$('#pass')?.value||'':'';
  if(mode==='2fa'){app.innerHTML=`<div class="login"><div class="auth glass view"><div class="eyebrow">SICO · SECURITY</div><h1>Код 2FA</h1><p class="muted">Открой Authenticator и введи 6-значный код для <b>${esc(data.login)}</b>.</p><input id="twoFactorCode" class="field" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="000000"><button class="accent wide" id="twoFactorBtn">Подтвердить</button><div class="switch" id="backAuth">← Назад</div></div></div>`;$('#twoFactorBtn').onclick=async()=>{const code=$('#twoFactorCode').value.trim();if(!/^\d{6}$/.test(code)){toast('Введи 6 цифр');return}try{const d=await api('/api/login/2fa',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login:data.login,password:data.password,code})});token=d.token;me=d.user;route='home';localStorage.setItem('sico_token',token);authScreenMode=null;connect();render('home')}catch(e){toast(e.message)}};$('#backAuth').onclick=()=>authView('login',false,{login:data.login});return;}
  if(mode==='recover'){
    app.innerHTML=`<div class="login"><div class="auth glass view"><div class="eyebrow">SICO · RECOVERY</div><h1>Восстановление</h1><p class="muted">Введи логин — покажем секретный вопрос.</p><input id="login" class="field" placeholder="Логин" autocomplete="username" value="${esc(oldLogin)}"><button class="accent wide" id="findAccount">Найти аккаунт</button><div class="switch" id="backAuth">← К входу</div></div></div>`;
    $('#findAccount').onclick=async()=>{const login=$('#login').value.trim();if(!login){toast('Введи логин');return}try{const d=await api('/api/recovery-question',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login})});authView('recoverAnswer',false,{login,question:d.question})}catch(e){toast(e.message)}};
    $('#backAuth').onclick=()=>authView('login');return;
  }
  if(mode==='recoverAnswer'){
    app.innerHTML=`<div class="login"><div class="auth glass view"><div class="eyebrow">SICO · RECOVERY</div><h1>Секретный вопрос</h1><p class="muted">${esc(data.question)}</p><input id="login" class="field" value="${esc(data.login)}" readonly><input id="secretAnswer" class="field" placeholder="Твой ответ"><button class="accent wide" id="checkAnswer">Проверить ответ</button><div class="switch" id="backAuth">← Назад</div></div></div>`;
    $('#checkAnswer').onclick=async()=>{const answer=$('#secretAnswer').value.trim();if(!answer){toast('Введи ответ');return}try{const d=await api('/api/forgot-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login:data.login,secretAnswer:answer})});authView('recoverReset',false,{login:data.login,recoveryToken:d.recoveryToken})}catch(e){toast(e.message)}};
    $('#backAuth').onclick=()=>authView('recover');return;
  }
  if(mode==='recoverReset'){
    app.innerHTML=`<div class="login"><div class="auth glass view"><div class="eyebrow">SICO · RECOVERY</div><h1>Новый пароль</h1><p class="muted">Старый пароль хранится в защищённом виде и не может быть показан. Задай новый пароль.</p><input id="login" class="field" value="${esc(data.login)}" readonly><input id="pass" class="field" type="password" placeholder="Новый пароль" autocomplete="new-password"><input id="pass2" class="field" type="password" placeholder="Повтори новый пароль" autocomplete="new-password"><button class="accent wide" id="resetBtn">Сменить пароль</button><div class="switch" id="backAuth">← К входу</div></div></div>`;
    $('#resetBtn').onclick=async()=>{const p1=$('#pass').value,p2=$('#pass2').value;if(p1!==p2){toast('Пароли не совпадают');return}try{await api('/api/reset-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recoveryToken:data.recoveryToken,newPassword:p1})});toast('Пароль изменён');authView('login',false,{login:data.login})}catch(e){toast(e.message)}};
    $('#backAuth').onclick=()=>authView('login',false,{login:data.login});return;
  }
  const oldQ=preserve?$('#secretQuestion')?.value||'':'';
  const oldA=preserve?$('#secretAnswer')?.value||'':'';
  const isReg=mode==='register';
  app.innerHTML=`<div class="login"><div class="auth glass view"><div class="eyebrow">SICO · LOCAL</div><h1>${isReg?'Создай аккаунт':'С возвращением'}</h1><p class="muted">${isReg?'Укажи логин, пароль и секретный вопрос для восстановления.':'Играй с друзьями в одной Wi‑Fi сети.'}</p><input id="login" class="field" placeholder="Логин" autocomplete="username" value="${esc(oldLogin)}"><input id="pass" class="field" type="password" placeholder="Пароль" autocomplete="${isReg?'new-password':'current-password'}" value="${esc(oldPass)}">${isReg?`<input id="secretQuestion" class="field" placeholder="Секретный вопрос" value="${esc(oldQ)}"><input id="secretAnswer" class="field" placeholder="Ответ на секретный вопрос" value="${esc(oldA)}">`:''}<button type="button" class="accent wide" id="authBtn">${isReg?'Создать аккаунт':'Войти'}</button>${!isReg?`<button type="button" class="ghost wide google-btn" id="googleAuthBtn">G&nbsp;&nbsp; Войти через Google</button><div class="switch" id="forgot">Забыли пароль?</div>`:''}<div class="switch" id="switch">${isReg?'Уже есть аккаунт? Войти':'Нет аккаунта? Создать'}</div><div class="auth-note">Локальная игра · без реальных денег</div></div></div>`;
  $('#authBtn').onclick=submitAuth;
  if(!isReg){const gb=$('#googleAuthBtn');if(gb)gb.onclick=googleLogin;}
  $('#switch').onclick=()=>{if(!authBusy)authView(isReg?'login':'register')};
  $('#forgot')?.addEventListener('click',()=>authView('recover'));
}
async function googleLogin(){if(authBusy)return;authBusy=true;try{const cfg=await api('/api/auth/google/config');if(!cfg.enabled){toast('Вход через Google пока не настроен на сервере');return}if(!window.google?.accounts?.id){await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src='https://accounts.google.com/gsi/client';sc.onload=resolve;sc.onerror=reject;document.head.appendChild(sc)})}const holder=document.createElement('div');holder.style.position='fixed';holder.style.inset='0';holder.style.zIndex='200';holder.style.display='grid';holder.style.placeItems='center';holder.style.background='rgba(0,0,0,.72)';holder.innerHTML='<div class="google-modal card"><h3>Вход через Google</h3><p class="muted">Подтверди аккаунт Google в окне ниже.</p><div id="googleBtn"></div><button class="ghost wide" id="googleCancel">Отмена</button></div>';document.body.append(holder);$('#googleCancel').onclick=()=>{holder.remove();authBusy=false};window.google.accounts.id.initialize({client_id:cfg.clientId,callback:async r=>{try{const d=await api('/api/auth/google',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({credential:r.credential})});token=d.token;me=d.user;route='home';localStorage.setItem('sico_token',token);authScreenMode=null;connect();holder.remove();render('home')}catch(e){toast(e.message)}finally{authBusy=false}}});window.google.accounts.id.renderButton($('#googleBtn'),{theme:'filled_black',size:'large',shape:'pill',text:'continue_with',width:280})}catch(e){authBusy=false;toast('Не удалось открыть Google Login')}}

async function submitAuth(e){
  e?.preventDefault();if(authBusy)return;
  const btn=$('#authBtn'),loginEl=$('#login'),passEl=$('#pass');if(!btn||!loginEl||!passEl)return;
  const login=loginEl.value.trim(),password=passEl.value,mode=authScreenMode;
  if(!login||!password){toast('Заполни логин и пароль');return}
  if(mode==='register'){
    const question=$('#secretQuestion')?.value.trim(),answer=$('#secretAnswer')?.value.trim();
    if(!question||!answer){toast('Заполни секретный вопрос и ответ');return}
    authBusy=true;btn.disabled=true;btn.textContent='Создаём…';
    try{const d=await api('/api/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login,password,secretQuestion:question,secretAnswer:answer})});token=d.token;me=d.user;route='home';localStorage.setItem('sico_token',token);authScreenMode=null;authBusy=false;connect();render('home')}catch(e){authBusy=false;btn.disabled=false;btn.textContent='Создать аккаунт';toast(e.message)}return;
  }
  authBusy=true;btn.disabled=true;btn.textContent='Входим…';
  try{const d=await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login,password})});if(d.twoFactorRequired){authBusy=false;authView('2fa',false,{login,password});return}token=d.token;me=d.user;route='home';localStorage.setItem('sico_token',token);authScreenMode=null;authBusy=false;connect();render('home')}catch(e){authBusy=false;btn.disabled=false;btn.textContent='Войти';toast(e.message)}
}
async function bootstrap(){
  // Never leave the form in a race with an async session check.
  if(token){
    app.innerHTML='<div class="login"><div class="auth glass view"><div class="eyebrow">SICO · LOCAL</div><h1>Загрузка…</h1><p class="muted">Проверяем локальную сессию.</p></div></div>';
    try{const d=await api('/api/me');me=d.user;booting=false;connect();render(location.hash.slice(1)||'home');return}catch(e){token=null;me=null;try{localStorage.removeItem('sico_token')}catch{}}
  }
  authView('login');
  // Do not connect WebSocket until a user is authenticated.
}
function ensureAmbient(){if(document.getElementById('sicoAmbient'))return;const a=document.createElement('div');a.id='sicoAmbient';a.className='ambient-layer';a.innerHTML=Array.from({length:18},(_,i)=>`<i style="--i:${i}"></i>`).join('');document.body.appendChild(a)}
function checkLevelUp(level){try{const n=Number(level)||1,key='sico:lastLevel',old=localStorage.getItem(key);if(old===null){localStorage.setItem(key,String(n));return}const prev=Number(old)||n;localStorage.setItem(key,String(n));if(n>prev)showLevelUp(n)}catch(e){}}
function showLevelUp(level){if(document.querySelector('.levelup-overlay'))return;sicoSound('levelup');const ov=document.createElement('div');ov.className='levelup-overlay';ov.innerHTML=`<div class="levelup-card"><div class="levelup-burst">✦</div><div class="eyebrow">PROGRESSION UNLOCKED</div><h2>LEVEL UP!</h2><div class="levelup-number">${level}</div><p>Новый уровень достигнут</p><button class="accent wide">Забрать</button></div>`;document.body.appendChild(ov);sicoSound('win');ov.onclick=e=>{if(e.target===ov||e.target.closest('button'))ov.remove()}}
function shell(content,title="SICO",sub="LOCAL PLAYGROUND"){document.body.dataset.theme=me?.theme||"graphite";document.body.dataset.route=route;ensureAmbient();const nav=[['home','⌂','Главная'],['games','🎮','Игры'],['social','♟','Соцсеть'],['profile','●','Профиль'],['more','☰','Ещё']];app.innerHTML=`<div class="shell" data-theme="${me.theme||"graphite"}"><header class="top"><button class="brand-logo" onclick="render('home')" aria-label="SICO — на главную"><img src="/sico-icon.svg" alt="SICO"><span>SICO<span class="brand-dot">.</span><small>LOCAL</small></span></button><div class="top-actions"><div class="online-pill">● ${state.online||0} online</div><div class="pill balance">◉ ${Number(me.balance).toLocaleString()} SC</div></div></header><main class="view"><div class="page-title"><div class="eyebrow">${sub}</div><h2>${title}</h2></div>${content}</main><nav class="nav">${nav.map(n=>`<button class="${route===n[0]?"active":""}" data-v="${n[0]}"><span>${n[1]}</span><small>${n[2]}</small></button>`).join("")}</nav></div>`;document.querySelectorAll(".nav button").forEach(b=>b.onclick=()=>render(b.dataset.v))}
function render(v){
  if(route!==v)sicoSound('tab');
  route=v;
  location.hash=v;
  const seq=++renderSeq;
  if(!me){authView();return}
  const fn=({home,games:gamesView,social:socialView,more:moreView,crash:crashView,roulette:rouletteView,cases:casesView,inventory:inventoryView,profile:profileView,history:historyView,achievements:achievementsView,bank:bankView,extras:extrasView,rules:rulesView,admin:adminView,progression:progressionView,security:securityView,blackjack:blackjackView,mines:minesView,dice:diceView,coinflip:coinFlipView,leaderboard:leaderboardView,plinko:plinkoView,hilo:hiloView,keno:kenoView,tower:towerView,diceduel:diceDuelView,baccarat:baccaratView,dailyspin:dailySpinView,upgrader:(...a)=>window.upgraderView(...a)}[v]||home);
  Promise.resolve(fn(seq)).catch(e=>{if(seq===renderSeq)toast(e.message||'Не удалось загрузить страницу')});
}
function progress(){return Math.round(me.xp/(me.level*1000)*100)}
async function home(seq=currentSeq()){let d=await api("/api/dashboard").catch(()=>null),daily=await api("/api/daily").catch(()=>({}));if(seq!==renderSeq||route!=='home')return;if(d){me=d.user;state.online=d.online}shell(`<section class="dashboard-hero"><div class="card hero-main"><div class="eyebrow">ТВОЙ ПРОГРЕСС</div><div class="hero-line"><div><h1>Привет, ${esc(me.login)}.</h1><p class="muted">Уровень ${me.level} · ${me.xp}/${me.level*1000} XP</p></div><div class="level-orb">${me.level}</div></div><div class="xp"><i style="width:${progress()}%"></i></div><div class="actions"><button class="accent" onclick="render('crash')">Играть сейчас <span>→</span></button><button class="ghost" onclick="render('extras')">Открыть всё</button></div></div><div class="card daily"><div class="eyebrow">DAILY DROP</div><div class="daily-num">${daily.streak||0}<span>дней</span></div><p class="muted">Ежедневный бонус с серией.</p><button class="ghost" id="dailyBtn" ${daily.claimed?"disabled":""}>${daily.claimed?"Уже забрано":"Забрать бонус"}</button></div></section><section class="mini-grid"><div class="card metric metric-online"><span>Игроков онлайн</span><b>${d?.online||state.online||0}</b><small>в локальной сети</small></div><div class="card metric"><span>Поддержка</span><b>${d?.support||0}</b><small>голосов от игроков</small></div><div class="card metric"><span>Достижения</span><b>${d?.achievements||0}</b><small>разблокировано</small></div><div class="card metric metric-crash-round"><span>Раунд Crash</span><b>#${d?.crash?.round||state.crash?.round||"—"}</b><small>${d?.crash?.multiplier?.toFixed?.(2)||"1.00"}x сейчас</small></div></section><section class="section-head"><div><div class="eyebrow">LIVE</div><h3>Игры</h3></div><button class="text-btn" onclick="render('extras')">Больше →</button></section><section class="grid"><article class="card game" onclick="render('crash')"><div class="game-icon">↗</div><div><div class="live-dot">● LIVE</div><h2>Crash</h2><p class="muted">Успей забрать до взрыва.</p></div><strong>${state.crash?.multiplier?.toFixed(2)||"1.00"}x</strong></article><article class="card game" onclick="render('roulette')"><div class="game-icon">◉</div><div><div class="live-dot">● LIVE</div><h2>Рулетка</h2><p class="muted">Красное, чёрное или зеро.</p></div><strong>${d?.roulette?.last?d.roulette.last.n:"—"}</strong></article><article class="card game" onclick="render('cases')"><div class="game-icon">◇</div><div><div class="live-dot">● OPEN</div><h2>Кейсы</h2><p class="muted">Открой случайную награду.</p></div><strong>3 кейса</strong></article></section><section class="card autumn-banner"><div class="section-head"><div><div class="eyebrow">AUTUMN 2026</div><h3>🍂 Осенний сезон SICO</h3><p class="muted">Сезонный Autumn Case · 1 200 SC · новые аватары, титулы, рамки и эффекты.</p></div><button class="accent" onclick="render('cases')">Смотреть →</button></div></section><section class="card" id="homeNews"><div class="section-head"><div><div class="eyebrow">SICO NEWS</div><h3>Новости мира SICO</h3></div><button class="text-btn" onclick="render('extras')">Все →</button></div><div class="feed" id="homeNewsList"><p class="muted">Загрузка новостей…</p></div></section><section class="split"><div class="card"><div class="section-head"><h3>Последние действия</h3><button class="text-btn" onclick="render('history')">История</button></div><div class="feed">${(d?.recent||[]).map(t=>`<div class="row"><div><b>${typeName(t.type)}</b><small>${new Date(t.at).toLocaleString()}</small></div><strong class="${t.delta>=0?"positive":"negative"}">${t.delta>0?"+":""}${t.delta} SC</strong></div>`).join("")||'<p class="muted">Здесь появится твоя активность.</p>'}</div></div><div class="card support-card"><div class="eyebrow">SICO</div><h3>Если нравится — поддержи</h3><p class="muted">Один аккаунт может оставить только один голос.</p><button class="ghost" id="supportBtn">♡ Поддержать проект</button></div></section><section class="card chat-teaser"><div><div class="eyebrow">SOCIAL</div><h3>Общий чат</h3><p class="muted">Общайся с друзьями прямо во время игры.</p></div><button class="accent" onclick="render('extras')">Открыть чат</button></section>`);$("#dailyBtn")?.addEventListener("click",claimDaily);$("#supportBtn")?.addEventListener("click",support);api('/api/news').then(n=>{const el=$("#homeNewsList");if(el)el.innerHTML=(n.items||[]).slice(0,4).map(x=>`<div class="news-row"><span class="news-icon">${esc(x.icon)}</span><div class="grow"><b>${esc(x.title)}</b><small>${esc(x.text)}</small></div></div>`).join('')||'<p class="muted">Новостей пока нет.</p>'}).catch(()=>{})}
function typeName(t){return ({crash_bet:"Ставка Crash",crash_win:"Выигрыш Crash",roulette_bet:"Ставка рулетки",roulette_win:"Выигрыш рулетки",case_open:"Открытие кейса",case_reward:"Награда кейса",daily_bonus:"Ежедневный бонус",loan_sent:"Займ отправлен",loan_received:"Займ получен",loan_payment:"Погашение займа",loan_repaid:"Займ погашен",scoin_buy:"Покупка SCoin",scoin_sell:"Продажа SCoin",bank_deposit:"Пополнение вклада",bank_withdraw:"Возврат вклада",plinko_bet:"Ставка Plinko",plinko_win:"Выигрыш Plinko",plinko_miss:"Промах Plinko",blackjack_bet:"Ставка Blackjack",blackjack_win:"Выигрыш Blackjack",blackjack_push:"Ничья Blackjack",hilo_bet:"Ставка Hi-Lo",hilo_win:"Выигрыш Hi-Lo",keno_bet:"Ставка Keno",keno_win:"Выигрыш Keno",tower_bet:"Ставка Tower",tower_win:"Выигрыш Tower",dice_duel_bet:"Ставка Dice Duel",dice_duel_win:"Выигрыш Dice Duel",dice_duel_push:"Ничья Dice Duel",baccarat_bet:"Ставка Baccarat",baccarat_win:"Выигрыш Baccarat",baccarat_push:"Ничья Baccarat",daily_spin:"Daily Spin",upgrader_bet:"Ставка Upgrader",upgrader_win:"Выигрыш Upgrader"}[t]||t)}
async function claimDaily(){try{const d=await api("/api/daily",{method:"POST",headers:{"X-Request-ID":rid()}});me=d.user;toast(`+${d.reward} SC · серия ${d.streak} 🔥`);render("home")}catch(e){toast(e.message)}}
async function support(){try{const x=await api("/api/support",{method:"POST"});toast("Спасибо за поддержку ♥");document.querySelector("#supportBtn").textContent="♥ Спасибо"}catch(e){toast(e.message)}}
function crashView(){const c=state.crash||{};shell(`<section class="card game-panel"><div class="gamehead"><span class="pill">ROUND #${c.round||"—"}</span><span class="status ${c.state}">${c.state==="running"?"● LIVE":c.state==="waiting"?"Подготовка":"Раунд завершён"}</span></div><div id="crashMult" class="mult ${c.state}">${Number(c.multiplier||1).toFixed(2)}<small>x</small></div><div id="crashHistory" class="crash-history">${(c.history||[]).map(x=>`<span>${x.x.toFixed(2)}x</span>`).join("")}</div><div class="betbar"><input id="crashAmount" class="field" type="number" min="1" placeholder="Ставка, SC"><button id="crashBetBtn" class="accent" onclick="betCrash()">Поставить</button><button class="ghost" onclick="cashCrash()">Забрать</button></div></section><section class="card"><div class="section-head"><h3>Игроки раунда</h3><span class="muted">${c.bets?.length||0} ставок</span></div><div id="crashBets" class="feed">${(c.bets||[]).map(b=>`<div class="person">${avatar({login:b.login})}<div class="grow"><b>${esc(b.login)}</b><small>${b.amount} SC</small></div><b class="${b.status==='cashed'?"positive":b.status==='lost'?"negative":"live-text"}">${b.status==='cashed'?b.cashout+'x':b.status==='active'?'LIVE':'LOST'}</b></div>`).join("")||'<p class="muted">Пока никто не поставил. Раунд продолжится.</p>'}</div></section>` ,"Crash","LIVE GAME")}

function updateCrashDOM(c){
  const mult=$("#crashMult");
  if(mult){mult.className="mult "+(c.state||"waiting");mult.innerHTML=Number(c.multiplier||1).toFixed(2)+"<small>x</small>";}
  const hist=$("#crashHistory");
  if(hist)hist.innerHTML=(c.history||[]).map(x=>`<span>${Number(x.x).toFixed(2)}x</span>`).join("");
  const bets=$("#crashBets");
  if(bets)bets.innerHTML=(c.bets||[]).map(b=>`<div class="person">${avatar({login:b.login})}<div class="grow"><b>${esc(b.login)}</b><small>${b.amount} SC</small></div><b class="${b.status==='cashed'?"positive":b.status==='lost'?"negative":"live-text"}">${b.status==='cashed'?b.cashout+'x':b.status==='active'?'LIVE':'LOST'}</b></div>`).join("")||'<p class="muted">Пока никто не поставил. Раунд продолжится.</p>';
  const betBtn=document.querySelector('#crashBetBtn'), amount=document.querySelector('#crashAmount');
  if(betBtn){betBtn.disabled=c.state!=="waiting";betBtn.textContent=c.state==="waiting"?"Поставить":c.state==="running"?"Ставки закрыты":"Ожидание";}
  if(amount)amount.disabled=c.state!=="waiting";
}
async function betCrash(){
  if(state.crash?.state!=="waiting"){toast("Ставки закрыты — раунд уже начался");return}
  try{const d=await api("/api/crash/bet",{method:"POST",headers:{"Content-Type":"application/json","X-Request-ID":rid()},body:JSON.stringify({amount:Number($("#crashAmount").value)})});me=d.user;sicoSound("bet");updateCrashDOM(state.crash);toast("Ставка принята")}catch(e){toast(e.message)}}
async function cashCrash(){try{const d=await api("/api/crash/cashout",{method:"POST",headers:{"X-Request-ID":rid()}});me=d.user;sicoSound("cashout");updateCrashDOM(state.crash);toast(`Забрано ${d.payout} SC @ ${d.multiplier}x`)}catch(e){toast(e.message)}}
const ROULETTE_ORDER=[0,32,15,19,4,21,2,25,17,34,6,27,13,36,11,30,8,23,10,5,24,16,33,1,20,14,31,9,22,18,29,7,28,12,35,3,26];
function rouletteGradient(){const step=360/37;return 'conic-gradient('+ROULETTE_ORDER.map((n,i)=>{const a=(i*step).toFixed(3),b=((i+1)*step).toFixed(3),col=n===0?'#2eae73':([1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36].includes(n)?'#b83e50':'#1f242c');return `${col} ${a}deg ${b}deg`}).join(',')+')'}
function rouletteTargetDeg(n){const idx=Math.max(0,ROULETTE_ORDER.indexOf(Number(n)));return -((idx+.5)*(360/37));}
function rouletteWheelHtml(r){const last=r.last?.n;const rot=last===undefined?0:rouletteTargetDeg(last);return `<div class="roulette-pointer" aria-hidden="true"></div><div class="roulette-wheel ${r.state==='spinning'?'spinning':''}" data-angle="${rot}" style="--roulette-bg:${rouletteGradient()};--roulette-angle:${rot}deg"><div class="roulette-ring"><span>0</span><span>00</span><span>♠</span><span>◆</span></div><div class="wheelcore">${r.state==='spinning'?'…':last??'SICO'}</div></div>`}
function rouletteView(){const r=state.roulette||{};shell(`<section class="card game-panel roulette-scene"><div class="gamehead"><span class="pill" id="rouletteRound">ROUND #${r.round||"—"}</span><span class="status ${r.state}" id="rouletteStatus">${r.state==='open'?'● Ставки открыты':r.state==='spinning'?'Вращение…':'Результат'}</span></div>${rouletteWheelHtml(r)}<div class="roulette-legend"><span>Европейская рулетка</span><b>${r.last?`${r.last.n} · ${r.last.color.toUpperCase()}`:'Ожидание'}</b></div><div class="colors"><button class="red" onclick="betRoulette('red')">RED <small>×2</small></button><button class="black" onclick="betRoulette('black')">BLACK <small>×2</small></button><button class="green" onclick="betRoulette('green')">GREEN <small>×14</small></button></div><input id="rouletteAmount" class="field" type="number" min="1" placeholder="Ставка, SC"></section><section class="card"><div class="section-head"><h3>Ставки раунда</h3><span class="muted">${r.bets?.length||0}</span></div><div class="feed" id="rouletteBets">${(r.bets||[]).map(b=>`<div class="person"><div class="grow"><b>${esc(b.login)}</b><small>${b.choice}</small></div><b>${b.amount} SC</b></div>`).join("")||'<p class="muted">Стань первым.</p>'}</div></section>` ,"Рулетка","LIVE GAME")}

async function betRoulette(c){try{const d=await api("/api/roulette/bet",{method:"POST",headers:{"Content-Type":"application/json","X-Request-ID":rid()},body:JSON.stringify({amount:Number($("#rouletteAmount").value),choice:c})});me=d.user;sicoSound("bet");toast("Ставка принята")}catch(e){toast(e.message)}}
function casesView(){const cases=[['Moon','◇','25–600 SC',160],['Nova','✦','100–2 500 SC',440],['Black','◆','250–8 000 SC',4000],['Vault','🎒','Косметические предметы',750],['Autumn','🍂','Осенние косметические предметы',1200]];const odds='Шансы: 25–45% · 50–25% · 75–15% · 120–8% · 200–5% · топ-дроп–2%';shell(`<section class="case-intro card"><div><div class="eyebrow">SICO AUTUMN 2026</div><h1>🍂 Осенний сезон</h1><p class="muted">Новый сезонный кейс с эксклюзивной косметикой. Награда определяется сервером.</p></div><div class="case-spark autumn-spark">🍁</div></section><section class="case-grid">${cases.map(c=>`<article class="card case ${c[0]==='Vault'?'cosmetic-case':''} ${c[0]==='Autumn'?'autumn-case':''}"><div class="casebox">${c[1]}</div><div><span class="rarity">${c[0]==='Vault'?'COSMETIC DROP':c[0]==='Autumn'?'SEASONAL DROP':'RANDOM DROP'}</span><h2>${c[0]}</h2><p class="muted">${c[2]}</p><small class="case-odds">${c[0]==='Vault'?'Аватары · статусы · титулы · значки · рамки · эффекты':c[0]==='Autumn'?'🍂 Autumn Fox · 🍁 Король листопада · 🧡 Autumn 2026 · 🍂 Leaffall · 🐿️ SICO Squirrel':'Шансы: '+odds}</small><button class="accent" onclick="openCase('${c[0]}')">Открыть · ${c[3].toLocaleString()} SC</button></div></article>`).join('')}</section><section class="card"><div class="section-head"><div><div class="eyebrow">SEASON PROGRESS</div><h3>Прогресс осени</h3></div><span class="pill">3 открытия → достижения</span></div><div class="autumn-progress"><div class="autumn-progressbar"><i id="autumnProgressFill" style="width:0%"></i></div><b id="autumnProgressText">Загрузка…</b></div></section><section class="card"><div class="section-head"><div><div class="eyebrow">YOUR ITEMS</div><h3>Инвентарь</h3></div><button class="ghost" onclick="render('inventory')">Открыть →</button></div><p class="muted">Vault Case и Autumn Case дают косметические предметы, которые можно экипировать в профиле.</p></section>` ,"Кейсы","COLLECTION");api('/api/autumn').then(d=>{const p=Math.min(100,Math.round((d.progress/d.goal)*100));const f=$('#autumnProgressFill'),t=$('#autumnProgressText');if(f)f.style.width=p+'%';if(t)t.textContent=`${d.progress}/${d.goal} Autumn Case · ${p}%`}).catch(()=>{})}
async function openCase(name){if(window.caseBusy)return;const card=[...document.querySelectorAll('.case')].find(x=>x.querySelector('h2')?.textContent===name);if(card)card.classList.add('case-opening');window.caseBusy=true;try{const d=await api('/api/cases/open',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({name})});me=d.user;sicoSound('win');const cosmetic=d.item;const content=cosmetic?`<div class="case-result-icon">${esc(cosmetic.icon)}</div><p class="muted">${esc(cosmetic.rarity)} · ${esc(cosmetic.type)}</p><strong>${esc(cosmetic.name)}</strong><h2>${esc(cosmetic.desc)}</h2>`:`<div class="case-result-icon">✦</div><p class="muted">Награда определена сервером</p><strong>+${Number(d.reward).toLocaleString()} SC</strong><h2>Красивый дроп</h2>`;const ov=document.createElement('div');ov.className='case-overlay';ov.innerHTML=`<div class="case-result"><div class="eyebrow">${esc(name.toUpperCase())} · DROP</div>${content}<button class="accent wide">Забрать</button></div>`;document.body.append(ov);ov.querySelector('button').onclick=()=>{ov.remove();render(cosmetic?'inventory':'cases');toast(cosmetic?`🎒 ${cosmetic.name} · ${cosmetic.rarity}`:`+${d.reward} SC · ${name}`)}}catch(e){toast(e.message);card?.classList.remove('case-opening')}finally{window.caseBusy=false}}

async function profileView(seq=currentSeq()){const [turn,inv]=await Promise.all([api("/api/turnover").catch(()=>({combined:0,incoming:0,outgoing:0})),api('/api/inventory').catch(()=>({items:[],equipped:{}}))]);if(seq!==renderSeq||route!=="profile")return;me=inv?.user||me;const themes=[['graphite','Graphite'],['ice','Ice'],['violet','Violet'],['lime','Lime'],['autumn','Autumn']];const v=me.profileVisibility||{};const visRows=[['avatar','Аватар'],['status','Статус'],['title','Титул'],['level','Уровень'],['xp','XP'],['stats','Статистика игр'],['trading','Trading P/L'],['achievements','Достижения'],['createdAt','Дата регистрации']];const equipped=inv?.equipped||me.equipped||{};shell(`<section class="card profile-card"><div class="profile"><div class="profile-art frame-${esc(equipped.frame?.value||'none')} effect-${esc(equipped.effect?.value||'none')}">${avatar({...me,equipped},'bigavatar')}</div><div><div class="eyebrow">PROFILE</div><h2>${esc(me.login)}</h2><p class="muted">${esc(me.status||'Новичок')} ${me.title?`· ${esc(me.title)}`:''}</p><p class="muted">Уровень ${me.level} · ${me.xp}/${me.level*1000} XP</p><div class="xp"><i style="width:${progress()}%"></i></div></div></div><div class="stats"><div class="stat"><span>Баланс</span><b class="profile-balance">${me.balance} SC</b></div><div class="stat"><span>Игры</span><b>${me.stats?.games||0}</b></div><div class="stat"><span>Достижения</span><b>${me.badges?.length||0}</b></div><div class="stat"><span>Trading P/L</span><b class="${Number(me.tradingPnl||0)>=0?'positive':'negative'}">${Number(me.tradingPnl||0)>=0?'+':''}${Number(me.tradingPnl||0).toLocaleString()} SC</b></div></div><label class="ghost upload">Сменить аватар<input id="avatar" type="file" accept="image/*" hidden></label></section><section class="card"><div class="section-head"><div><div class="eyebrow">PROFILE TEXT</div><h3>Статус и титул</h3></div></div><input id="profileStatus" class="field" maxlength="80" placeholder="Статус" value="${esc(me.status||'Новичок')}"><input id="profileTitle" class="field" maxlength="80" placeholder="Титул" value="${esc(me.title||'')}"><button class="accent" onclick="saveProfileSettings()">Сохранить профиль</button></section><section class="card"><div class="section-head"><div><div class="eyebrow">PRIVACY</div><h3>Что видят другие игроки</h3></div><span class="muted">По умолчанию всё видно</span></div><div class="privacy-grid">${visRows.map(([k,label])=>`<label class="privacy-row"><span>${label}</span><input type="checkbox" class="privacy-toggle" data-key="${k}" ${v[k]!==false?'checked':''}></label>`).join('')}</div><button class="accent" onclick="saveProfileVisibility()">Сохранить видимость</button></section><section class="card"><div class="section-head"><div><div class="eyebrow">INVENTORY</div><h3>Экипировка</h3></div><button class="ghost" onclick="render('inventory')">Открыть инвентарь →</button></div><p class="muted">Экипируй предметы из Vault Case: аватары, статусы, титулы, значки, рамки и эффекты.</p></section><section class="card"><div class="section-head"><div><div class="eyebrow">TURNOVER</div><h3>Оборот</h3></div></div><div class="turnover-grid"><div class="stat"><span>Средняя операция</span><b>${turn.combined||0} SC</b></div><div class="stat"><span>Средняя трата</span><b>${turn.outgoing||0} SC</b></div><div class="stat"><span>Среднее получение</span><b>${turn.incoming||0} SC</b></div></div></section><section class="card"><div class="section-head"><div><div class="eyebrow">STYLE</div><h3>Оформление</h3></div></div><div class="themes">${themes.map(t=>`<button class="theme theme-${t[0]} ${me.theme===t[0]?"selected":""}" onclick="setTheme('${t[0]}')"><span></span>${t[1]}</button>`).join('')}</div></section><section class="card"><div class="actions"><button class="ghost" onclick="render('bank')">Открыть банк</button><button class="ghost" onclick="render('history')">История операций</button><button class="ghost" onclick="render('achievements')">Достижения</button><button class="ghost" onclick="render('progression')">Прогрессия</button><button class="ghost" onclick="render('security')">Безопасность</button><button class="ghost" onclick="logout()">Выйти</button><button class="danger" onclick="deleteAccount()">Удалить аккаунт</button></div></section>` ,"Профиль","ACCOUNT");$('#avatar').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>25*1024*1024)return toast('Максимум 25 МБ');const fd=new FormData();fd.append('avatar',f);try{const d=await api('/api/avatar',{method:'POST',body:fd});me=d.user;toast('Аватар обновлён');render('profile')}catch(e){toast(e.message)}}}
async function saveProfileSettings(){try{const d=await api('/api/profile/settings',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({status:$('#profileStatus')?.value||'',title:$('#profileTitle')?.value||''})});me=d.user;toast('Профиль обновлён');render('profile')}catch(e){toast(e.message)}}
async function saveProfileVisibility(){try{const visibility={};document.querySelectorAll('.privacy-toggle').forEach(x=>visibility[x.dataset.key]=x.checked);const d=await api('/api/profile/settings',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({visibility})});me=d.user;toast('Видимость сохранена');render('profile')}catch(e){toast(e.message)}}
function inventoryItemHtml(x,eq){return `<article class="inventory-item ${eq?'equipped':''}"><div class="inventory-icon">${esc(x.icon)}</div><div class="grow"><b>${esc(x.name)}</b><small>${esc(x.rarity)} · ${esc(x.desc)}</small></div><button class="ghost" onclick="equipInventory('${x.id}')">${eq?'Экипировано':'Экипировать'}</button></article>`}
async function inventoryView(seq=currentSeq()){const d=await api('/api/inventory');if(seq!==renderSeq||route!=='inventory')return;const groups=['avatar','status','title','badge','frame','effect'];const byType=Object.fromEntries(groups.map(g=>[g,d.items.filter(x=>x.type===g)]));const typeNames={avatar:'Аватары',status:'Статусы',title:'Титулы',badge:'Значки',frame:'Рамки',effect:'Эффекты'};const sections=groups.map(g=>{const items=byType[g].map(x=>inventoryItemHtml(x,d.equipped?.[g]===x.id)).join('')||'<p class="muted">Пока пусто. Открой Vault Case.</p>';return `<section class="card"><div class="section-head"><div><div class="eyebrow">${esc(typeNames[g])}</div><h3>${byType[g].length||0}</h3></div></div><div class="inventory-grid">${items}</div></section>`}).join('');shell(`<section class="card"><div class="eyebrow">SICO VAULT</div><h1>🎒 Инвентарь</h1><p class="muted">Предметы из Vault Case за ${d.cosmeticCase?.cost||750} SC и сезонного Autumn Case. Выбранные предметы показываются в публичном профиле.</p><div class="actions"><button class="accent" onclick="render('cases')">Открыть Vault Case</button><button class="ghost" onclick="render('profile')">Настройки профиля</button></div></section>${sections}`,'Инвентарь','COLLECTION')}
async function equipInventory(itemId){try{const d=await api('/api/inventory/equip',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({itemId})});me=d.user;toast('Предмет экипирован');render('inventory')}catch(e){toast(e.message)}}
function feeForClient(n){return Math.ceil(Math.max(0,Number(n)||0)*0.15)}
function formatDuration(ms){const total=Math.max(0,Math.floor(Number(ms)||0)/1000);const d=Math.floor(total/86400),h=Math.floor((total%86400)/3600),m=Math.floor((total%3600)/60),s=Math.floor(total%60);if(d)return `${d}д ${String(h).padStart(2,"0")}ч`;if(h)return `${h}ч ${String(m).padStart(2,"0")}м`;return `${String(m).padStart(2,"0")}м ${String(s).padStart(2,"0")}с`}
function userName(id){const p=(window._players||[]).find(x=>x.id===id);return p?.login||id||"игрок"}
async function setTheme(theme){try{const d=await api("/api/theme",{method:"POST",headers:{"Content-Type":"application/json","X-Request-ID":rid()},body:JSON.stringify({theme})});me=d.user;document.body.dataset.theme=me.theme;document.querySelector('.shell')?.setAttribute('data-theme',me.theme);toast("Тема изменена");render("profile")}catch(e){toast(e.message)}}
async function bankView(seq=currentSeq()){
  const tab=window.bankTab||'bank';
  if(tab==='trading')return tradingView(seq);
  const d=await api("/api/bank/overview").catch(()=>({balance:me.balance,feePercent:15,loans:[],transactions:[]}));
  if(seq!==renderSeq||route!=="bank")return;
  if(d.players)window._players=d.players;
  const incoming=d.loans.filter(l=>l.to===me.id&&l.status==="pending"),open=d.loans.filter(l=>l.to===me.id&&l.status==="open"),given=d.loans.filter(l=>l.from===me.id&&l.status!=="declined");
  shell(`<section class="bank-hero card"><div><div class="eyebrow">SICO BANK</div><h1>Внутренний банк</h1><p class="muted">Переводы, займы, SCoin и история — в одном месте.</p></div><div class="bank-total"><span>Баланс</span><strong>${Number(me.balance).toLocaleString()} SC</strong></div></section><div class="bank-tabs"><button class="ghost selected" onclick="window.bankTab='bank';bankView()">🏦 Банк</button><button class="ghost" onclick="window.bankTab='trading';bankView()">📈 Трейдинг</button></div><section class="bank-grid"><div class="card"><div class="eyebrow">TRANSFER</div><h3>Перевести SC</h3><p class="muted">Получатель получает указанную сумму. Комиссия банка — 15% и исчезает из экономики.</p><div class="loan-grid"><input id="transferLogin" class="field" placeholder="Логин игрока"><input id="transferAmount" class="field" type="number" min="1" placeholder="Сумма, SC"><button class="accent" onclick="transferSC()">Перевести</button></div></div><div class="card"><div class="eyebrow">LOAN</div><h3>Выдать займ</h3><p class="muted">Укажи сумму. Срок 1 или 2 суток выберет получатель при принятии займа. Комиссия — 15%.</p><div class="loan-grid"><input id="loanLogin" class="field" placeholder="Логин игрока"><input id="loanAmount" class="field" type="number" min="1" placeholder="Сумма, SC"><button class="accent" onclick="loan()">Предложить займ</button></div><small class="muted">Займ 1 000 SC потребует 1 150 SC у выдающего. Получатель сам выберет срок.</small></div></section>${incoming.length?`<section class="card"><div class="section-head"><div><div class="eyebrow">INCOMING</div><h3>Запросы на займ</h3></div></div>${incoming.map(l=>`<div class="loan-request"><div><b>${esc(userName(l.from))} предлагает ${l.principal} SC</b><small>Срок выберешь при принятии · комиссия ${l.fee||feeForClient(l.principal)} SC · к возврату ${l.principal+feeForClient(l.principal)} SC</small></div><div class="actions loan-choice"><button class="accent" onclick="acceptLoan('${l.id}',1)">1 сутки</button><button class="accent" onclick="acceptLoan('${l.id}',2)">2 суток</button><button class="ghost" onclick="declineLoan('${l.id}')">Отклонить</button></div></div>`).join('')}</section>`:''}<section class="card"><div class="section-head"><div><div class="eyebrow">ACTIVE LOANS</div><h3>Активные займы</h3></div><span class="pill">15% комиссия</span></div>${[...open,...given.filter(l=>l.status==='open')].map(l=>{const lender=l.from===me.id,who=lender?userName(l.to):userName(l.from),left=l.dueAt?Math.max(0,l.dueAt-Date.now()):0;return `<div class="row loan-row"><div class="grow"><b>${lender?'Ты → '+esc(who):'Тебе ← '+esc(who)}</b><small>${lender?'Выдано':'Получено'} · ${l.principal} SC · срок ${l.days} ${l.days===1?'сутки':'суток'} · осталось <span class="loan-countdown" data-due="${l.dueAt}">${formatDuration(left)}</span> · к возврату ${l.principal+feeForClient(l.principal)} SC</small></div><div class="loan-actions">${!lender?`<button class="accent" onclick="repayLoan('${l.id}')">Вернуть долг</button>`:''}<strong>${l.principal} SC</strong></div></div>`}).join('')||'<p class="muted">Активных займов нет.</p>'}</section><section class="card"><div class="section-head"><div><div class="eyebrow">BANK LEDGER</div><h3>Последние операции</h3></div><button class="text-btn" onclick="render('history')">Вся история →</button></div><div class="feed">${d.transactions.slice(0,10).map(t=>`<div class="row"><div><b>${typeName(t.type)}</b><small>${new Date(t.at).toLocaleString()}</small></div><strong class="${t.delta>=0?'positive':'negative'}">${t.delta>0?'+':''}${t.delta} SC</strong></div>`).join('')||'<p class="muted">Операций пока нет.</p>'}</div></section>` ,"Банк","SICO FINANCE");
}
function updateLoanCountdowns(){document.querySelectorAll('.loan-countdown').forEach(el=>{const due=Number(el.dataset.due||0);el.textContent=formatDuration(Math.max(0,due-Date.now()))})}
if(!window.loanCountdownTimer)window.loanCountdownTimer=setInterval(updateLoanCountdowns,1000);
function tradingChart(history){
  const h=(history||[]).slice(-60); if(!h.length)return '<div class="trading-empty">Загрузка графика…</div>';
  const w=900,hh=300,pad=24,vals=h.map(x=>Number(x.price)||0),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(max-min,0.000001);
  const pts=vals.map((v,i)=>`${pad+i*(w-pad*2)/Math.max(1,vals.length-1)},${hh-pad-((v-min)/range)*(hh-pad*2)}`).join(' ');
  const first=vals[0],last=vals[vals.length-1],pct=((last/first-1)*100); const cls=pct>=0?'positive':'negative';
  return `<div class="trading-chart"><svg viewBox="0 0 ${w} ${hh}" preserveAspectRatio="none" aria-label="График SCoin"><defs><linearGradient id="scg" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="currentColor" stop-opacity=".22"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><polyline class="chart-line" points="${pts}" fill="none" vector-effect="non-scaling-stroke"/><polygon class="chart-fill" points="${pad},${hh-pad} ${pts} ${w-pad},${hh-pad}"/></svg><div class="chart-meta"><span>${first.toFixed(4)} SC</span><b class="${cls}">${pct>=0?'+':''}${pct.toFixed(2)}%</b><span>${last.toFixed(4)} SC</span></div></div>`;
}
async function tradingView(seq=currentSeq()){
  const d=await api('/api/trading').catch(()=>null);if(!d||seq!==renderSeq||route!=='bank')return;
  shell(`<section class="bank-hero card"><div><div class="eyebrow">SCOIN MARKET</div><h1>SCoin Trading</h1><p class="muted">Виртуальная криптовалюта SICO. Курс меняется сервером раз в 2 минуты и иногда делает сильные движения.</p></div><div class="bank-total"><span>Цена SCoin</span><strong id="scoinPrice">${Number(d.price).toFixed(4)} SC</strong></div></section><div class="bank-tabs"><button class="ghost" onclick="window.bankTab='bank';bankView()">🏦 Банк</button><button class="ghost selected" onclick="window.bankTab='trading';bankView()">📈 Трейдинг</button></div><section class="trading-grid"><div class="card trading-main"><div class="section-head"><div><div class="eyebrow">LIVE MARKET</div><h3>График SCoin</h3></div><span class="pill" id="marketTick">Обновление каждые 2 мин</span></div><div id="scoinChart">${tradingChart(d.history)}</div><div class="market-stats"><div><span>У тебя</span><b id="scoinHoldings">${Number(d.scCoin||0).toFixed(4)} SCoin</b></div><div><span>Покупка</span><b>0% комиссии</b></div><div><span>Продажа</span><b>15% комиссии</b></div><div><span>Следующий тик</span><b id="marketCountdown">—</b></div></div></div><div class="card"><div class="eyebrow">TRADE</div><h3>Купить SCoin</h3><p class="muted">Вводишь сумму в SC. При покупке комиссии нет — вся сумма превращается в SCoin.</p><input id="scoinBuyAmount" class="field" type="number" min="1" placeholder="Сумма в SC"><button class="accent wide" onclick="buySCoin()">Купить SCoin</button><hr class="soft-hr"><div class="eyebrow">SELL</div><h3>Продать SCoin</h3><p class="muted">Продажа идёт по текущему курсу; при продаже удерживается 15% комиссии.</p><input id="scoinSellAmount" class="field" type="number" min="0.000001" step="0.000001" placeholder="Количество SCoin"><button class="ghost wide" onclick="sellSCoin()">Продать SCoin</button></div></section><section class="card"><div class="section-head"><div><div class="eyebrow">ABOUT SCOIN</div><h3>Как работает рынок</h3></div></div><div class="feed"><div class="row"><b>Курс</b><span>Меняется каждые 2 минуты случайным движением вверх или вниз.</span></div><div class="row"><b>Рынок</b><span>Один общий курс для всех игроков этого сервера.</span></div><div class="row"><b>Комиссия</b><span>Покупка — 0%. Продажа — 15%. Комиссия при продаже просто исчезает из экономики.</span></div><div class="row"><b>Риск</b><span>SCoin — игровая виртуальная валюта. Цена может как расти, так и падать.</span></div></div></section>`,'Трейдинг','SICO MARKET');
  startMarketCountdown(d.lastTick);
}
function startMarketCountdown(lastTick){if(window.marketTimer)clearInterval(window.marketTimer);const update=()=>{const el=$('#marketCountdown');if(!el)return;const left=Math.max(0,120000-(Date.now()-Number(lastTick||Date.now())));el.textContent=left<=0?'обновление скоро':Math.ceil(left/1000)+' сек'};update();window.marketTimer=setInterval(update,1000)}
async function buySCoin(){try{const amount=Math.floor(Number($('#scoinBuyAmount').value));const d=await api('/api/trading/buy',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount})});me=d.user;sicoSound('bet');toast(`Куплено ${Number(d.coinQty).toFixed(4)} SCoin · комиссия ${d.fee} SC`);tradingView(renderSeq)}catch(e){toast(e.message)}}
async function sellSCoin(){try{const amount=Number($('#scoinSellAmount').value);const d=await api('/api/trading/sell',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount})});me=d.user;sicoSound('win');toast(`Продано ${Number(d.coinQty).toFixed(4)} SCoin · получено ${d.net} SC`);tradingView(renderSeq)}catch(e){toast(e.message)}}

async function loan(){try{const amount=Math.floor(Number($("#loanAmount").value));await api("/api/loan",{method:"POST",headers:{"Content-Type":"application/json","X-Request-ID":rid()},body:JSON.stringify({login:$("#loanLogin").value,amount})});sicoSound("bet");toast("Запрос займа отправлен");render("bank")}catch(e){toast(e.message)}}
async function transferSC(){try{const amount=Math.floor(Number($("#transferAmount").value));const d=await api("/api/transfer",{method:"POST",headers:{"Content-Type":"application/json","X-Request-ID":rid()},body:JSON.stringify({login:$("#transferLogin").value,amount})});me=d.user;sicoSound("bet");toast(`Переведено ${d.amount} SC · комиссия ${d.fee} SC`);render("bank")}catch(e){toast(e.message)}}
async function acceptLoan(id,days){if(![1,2].includes(Number(days)))return toast("Выбери 1 или 2 суток");try{const d=await api(`/api/loan/${id}/accept`,{method:"POST",headers:{"Content-Type":"application/json","X-Request-ID":rid()},body:JSON.stringify({days:Number(days)})});me=d.user;sicoSound("win");toast(`+${d.loan.principal} SC · срок ${days} ${days===1?'сутки':'суток'}`);render("bank")}catch(e){toast(e.message)}}
async function repayLoan(id){if(!confirm("Вернуть весь долг вместе с комиссией 15%?"))return;try{const d=await api(`/api/loan/${id}/pay`,{method:"POST",headers:{"X-Request-ID":rid()}});me=d.user;sicoSound("win");toast("Долг полностью погашен");render("bank")}catch(e){toast(e.message)}}
async function declineLoan(id){try{await api(`/api/loan/${id}/decline`,{method:"POST",headers:{"X-Request-ID":rid()}});sicoSound("click");toast("Запрос отклонён");render("bank")}catch(e){toast(e.message)}}
async function historyView(seq=currentSeq()){const h=await api("/api/history");if(seq!==renderSeq||route!=='history')return;shell(`<section class="card"><div class="section-head"><div><div class="eyebrow">LEDGER</div><h3>История операций</h3></div><span class="muted">${h.transactions.length}</span></div><div class="feed">${h.transactions.map(t=>`<div class="row"><div><b>${typeName(t.type)}</b><small>${new Date(t.at).toLocaleString()}</small></div><strong class="${t.delta>=0?'positive':'negative'}">${t.delta>0?'+':''}${t.delta} SC</strong></div>`).join("")||'<p class="muted">Пока пусто.</p>'}</div></section><section class="card"><div class="section-head"><h3>Игровые результаты</h3></div><div class="feed">${h.bets.map(b=>`<div class="row"><div><b>${b.game.toUpperCase()}</b><small>${b.status} · ${new Date(b.at).toLocaleString()}</small></div><span>${b.amount} SC</span></div>`).join("")||'<p class="muted">Раундов пока нет.</p>'}</div></section>` ,"История","ACTIVITY")}
async function achievementsView(seq=currentSeq()){const a=await api("/api/achievements");if(seq!==renderSeq||route!=='achievements')return;const icons=['✦','↗','◉','◆','♛','☼','◌','✉','♢','⚡','★','⌁','◇','♜','✧','◎','∞'];shell(`<section class="card achievement-summary"><div><div class="eyebrow">SICO COLLECTION</div><h3>Твои достижения</h3><p class="muted">${a.defs.filter(x=>x.unlocked).length} из ${a.defs.length} открыто. Выполняй разные действия в игре, чтобы собирать бейджи.</p></div><strong>${a.defs.filter(x=>x.unlocked).length}/${a.defs.length}</strong></section><section class="achievement-grid">${a.defs.map((x,i)=>`<article class="card achievement ${x.unlocked?'unlocked':''}"><div class="badge">${x.unlocked?icons[i%icons.length]:'○'}</div><div><h3>${x.title}</h3><p class="muted">${x.desc}</p></div><span>${x.unlocked?'ГОТОВО':'LOCKED'}</span></article>`).join("")}</section>` ,"Достижения","PROGRESS")}
async function extrasView(seq=currentSeq()){const players=await api('/api/players').catch(()=>[]);window._players=players;const chat=await api('/api/chat').catch(()=>({messages:[]}));if(seq!==renderSeq||route!=='extras')return;shell(`<section class="split"><div class="card"><div class="section-head"><div><div class="eyebrow">PLAYERS</div><h3>Игроки</h3></div><span class="muted">${state.online} online</span></div><div class="player-grid">${players.map(p=>`<div class="person player-click" onclick="showPlayer('${p.id}')">${avatar(p)}<div class="grow"><b>${esc(p.login)}</b><small>Уровень ${p.level}${p.title?' · '+esc(p.title):''}</small></div><span>${p.balance} SC</span></div>`).join('')||'<p class="muted">Игроков пока нет.</p>'}</div></div><div class="card chat"><div class="section-head"><div><div class="eyebrow">GLOBAL CHAT</div><h3>Общий чат</h3></div><span class="muted">LIVE · 30</span></div><div class="chat-list" id="chatList">${chat.messages.slice().reverse().map(chatMsg).join('')}</div><div class="chatbar"><input id="chatInput" class="field" maxlength="280" placeholder="Написать сообщение…"><button id="chatSendBtn" class="accent" onclick="sendChat()">→</button></div></div></section>` ,'Общее','SICO HUB');$('#chatInput')?.addEventListener('keydown',e=>{if(e.key==='Enter')sendChat()})}
async function leaderboardView(){const modes=[['balance','Баланс'],['level','Уровень'],['scoin','SCoin'],['achievements','Достижения']];const mode=window.lbMode||'balance';const d=await api('/api/leaderboard?mode='+mode);const unit={balance:'SC',level:'LVL',scoin:'SCoin',achievements:'шт.'};shell(`<section class="card"><div class="section-head"><div><div class="eyebrow">LOCAL RANKING</div><h3>Лидерборд</h3><p class="muted">Отдельные таблицы по четырём показателям.</p></div><span class="pill">${d.mode}</span></div><div class="leader-tabs">${modes.map(x=>`<button class="ghost ${mode===x[0]?'selected':''}" onclick="window.lbMode='${x[0]}';leaderboardView()">${x[1]}</button>`).join('')}</div><div class="feed leaderboard">${d.rows.map((p,i)=>`<div class="row player-click" onclick="showPlayer('${p.id}')"><div class="rank">${i+1}</div>${avatar(p)}<div class="grow"><b>${esc(p.login)}</b><small>LVL ${p.level}${p.title?' · '+esc(p.title):''}</small></div><strong>${Number(p.value).toLocaleString()} ${unit[mode]}</strong></div>`).join('')||'<p class="muted">Пока нет игроков.</p>'}</div></section>`,'Лидерборд','LOCAL RANKING')}

let plinkoBusy=false;
function plinkoBoard(path=[],result=null){const rows=12,cols=13,pegs=[];for(let r=0;r<rows;r++){for(let c=0;c<13;c++){const x=50+(c-6)*(5.7)+(r%2?2.85:0);if(x>5&&x<95)pegs.push(`<i class="plinko-peg" style="left:${x}%;top:${8+r*6.2}%"></i>`)}}const slotVals=[0.75,1.2,1.5,2,3,5,10,5,3,2,1.5,1.2,0.75];const slots=slotVals.map((v,i)=>`<div class="plinko-slot ${v>=5?'hot':''} ${result?.slot===i?'landed':''}"><b>${v===10?'X10':'X'+v.toFixed(2).replace(/\.00$/,'')}</b></div>`).join('');return `<div class="plinko-board" id="plinkoBoard">${pegs.join('')}<div class="plinko-path"></div><div class="plinko-ball" id="plinkoBall"></div><div class="plinko-slots">${slots}</div></div>`}
async function plinkoPlay(){if(plinkoBusy)return;const amount=Math.floor(Number($('#plinkoAmount')?.value));if(!Number.isSafeInteger(amount)||amount<1||amount>100000)return toast('Ставка: от 1 до 100 000 SC');plinkoBusy=true;const btn=$('#plinkoBtn');if(btn)btn.disabled=true;try{const d=await api('/api/plinko/play',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount})});me=d.user;const board=$('#plinkoBoard');if(board){const ball=$('#plinkoBall');const pts=d.path||[];ball.style.left=(pts[0]?.x??50)+'%';ball.style.top=(pts[0]?.y??2)+'%';ball.getAnimations().forEach(a=>a.cancel());ball.animate(pts.map(p=>({left:p.x+'%',top:p.y+'%'})),{duration:Math.max(2400,pts.length*115),easing:'cubic-bezier(.2,.75,.25,1)',fill:'forwards'});sicoSound('plinko');setTimeout(()=>{if(d.miss){sicoSound('miss');toast('Шарик пролетел мимо лунок · ставка потеряна')}else if(d.payout>=amount){sicoSound('win');toast(`X${d.multiplier} · +${d.payout.toLocaleString()} SC`)}else{sicoSound('lose');toast(`X${d.multiplier} · ${d.payout.toLocaleString()} SC`) }},Math.max(2400,pts.length*115)-80)}else{toast(d.miss?'Шарик промахнулся':`X${d.multiplier} · ${d.payout} SC`)}setTimeout(()=>{plinkoBusy=false;render('plinko')},Math.max(2700,(d.path?.length||12)*120))}catch(e){plinkoBusy=false;if(btn)btn.disabled=false;toast(e.message)}}
function plinkoView(){shell(`<section class="card game-panel plinko-panel"><div class="gamehead"><div><div class="eyebrow">NEW · PLINKO</div><h1>Plinko</h1><p class="muted">Поставь SC и отпусти шарик. Он меняет траекторию на каждом ряду.</p></div><span class="pill">X0 → X10</span></div>${plinkoBoard()}<div class="plinko-legend"><span>Малый множитель</span><span>Центр · X10</span><span>Промах · 0</span></div><div class="plinko-controls"><input id="plinkoAmount" class="field" type="number" min="1" max="100000" value="10" placeholder="Ставка, SC"><button id="plinkoBtn" class="accent" onclick="plinkoPlay()">Запустить шарик</button></div></section><section class="card"><div class="section-head"><h3>Множители</h3><span class="muted">Центр — X10</span></div><div class="plinko-payouts">${[0.75,1.2,1.5,2,3,5,10,5,3,2,1.5,1.2,0.75].map(v=>`<span class="${v>=5?'hot':''}">X${v}</span>`).join('')}</div><p class="muted plinko-note">Результат определяется сервером до анимации. Иногда шарик может уйти за край и не попасть ни в одну лунку.</p></section>`,'Plinko','NEW GAME')}

function setGameFilter(filter,btn){
  const buttons=document.querySelectorAll('.game-filter');buttons.forEach(x=>{x.classList.toggle('active',x.dataset.filter===filter);x.setAttribute('aria-pressed',x.dataset.filter===filter?'true':'false')});
  const cards=[...document.querySelectorAll('.game-grid .game-tile')];let shown=0;
  cards.forEach(card=>{const show=filter==='all'||card.dataset.group===filter;card.style.display=show?'':'none';if(show)shown++});
  const featured=document.querySelector('.game-featured'),soon=document.querySelector('.coming-soon-card');if(featured)featured.style.display=filter==='all'?'':'none';if(soon)soon.style.display=filter==='all'?'':'none';
  const empty=document.querySelector('.game-filter-empty');if(empty)empty.style.display=shown?'none':'block';
}
