function gameCardButton(value,label,active=false){return `<button class="ghost ${active?'active':''}" onclick="document.querySelectorAll('.game-card-btn').forEach(x=>x.classList.remove('active'));this.classList.add('active');window._selectedGameChoice='${value}'">${label}</button>`}
function cardLabelSafe(c){try{return cardLabel(c)}catch{return String(c)}}
function simpleCard(c){return `<span class="playing-card">${esc(cardLabelSafe(c))}</span>`}
async function hiloView(seq=currentSeq()){
  const d=await api('/api/hilo/state').catch(()=>({game:null}));if(seq!==renderSeq||route!=='hilo')return;const g=d.game;
  shell(`<section class="card game-panel hilo-scene"><div class="eyebrow">HIGH OR LOW</div><div class="gamehead"><div><h1>↕ Hi-Lo</h1><p class="muted">Угадай следующую карту. Правильный выбор поднимает множитель.</p></div><span class="pill">${g?`X${g.multiplier}`:'START'}</span></div>${g?`<div class="hilo-card-wrap">${simpleCard(g.current)}</div><div class="hilo-meta"><div><span>Раунд</span><b>${g.rounds}</b></div><div><span>Множитель</span><b>${g.multiplier}x</b></div><div><span>Забрать</span><b>${Math.floor(g.amount*g.multiplier)} SC</b></div></div><div class="actions"><button class="ghost" onclick="hiloGuess('lower')">↓ НИЖЕ</button><button class="accent" onclick="hiloGuess('higher')">↑ ВЫШЕ</button><button class="ghost" onclick="hiloCashout()">Забрать ${Math.floor(g.amount*g.multiplier)} SC</button></div>`:`<div class="betbar"><input id="hiloAmount" class="field" type="number" min="1" value="10" placeholder="Ставка, SC"><button class="accent" onclick="hiloStart()">Начать раунд</button></div>`}</section><section class="card"><h3>Как играть</h3><p class="muted">Каждое верное угадывание увеличивает множитель. Ошибка завершает раунд без выплаты. После первой победы можно забрать сумму.</p></section>`,'Hi-Lo','STRATEGY GAME')
}
async function hiloStart(){try{const d=await api('/api/hilo/start',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount:Number($('#hiloAmount').value)})});me=d.user;sicoSound('bet');render('hilo')}catch(e){toast(e.message)}}
async function hiloGuess(guess){try{const d=await api('/api/hilo/guess',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({guess})});me=d.user;sicoSound(d.win?'win':'lose');toast(d.win?`Верно · X${d.game.multiplier}`:'Не угадал · ставка потеряна');render('hilo')}catch(e){toast(e.message)}}
async function hiloCashout(){try{const d=await api('/api/hilo/cashout',{method:'POST',headers:{'X-Request-ID':rid()}});me=d.user;sicoSound('cashout');toast(`Забрано ${d.game.payout} SC · +${d.game.profit} SC`);render('hilo')}catch(e){toast(e.message)}}

function kenoNumbersHtml(selected=[]){const set=new Set(selected);return Array.from({length:40},(_,i)=>{const n=i+1;return `<button class="keno-num ${set.has(n)?'selected':''}" data-number="${n}" onclick="toggleKeno(${n},this)">${n}</button>`}).join('')}
function kenoView(){shell(`<section class="card game-panel keno-scene"><div class="eyebrow">NUMBERS</div><h1>№ Keno</h1><p class="muted">Выбери от 2 до 10 чисел. Сервер вытянет 10 чисел из 40.</p><div class="keno-grid" id="kenoGrid">${kenoNumbersHtml([])}</div><div class="keno-bar"><span id="kenoSelected">0 / 10</span><input id="kenoAmount" class="field" type="number" min="1" value="10" placeholder="Ставка, SC"><button class="accent" onclick="playKeno()">Разыграть</button></div><div id="kenoResult"></div></section><section class="card"><div class="section-head"><h3>Выплаты</h3><span class="muted">10 совпадений = X2500</span></div><div class="payout-line"><span>3 → X2</span><span>4 → X4</span><span>5 → X12</span><span>6 → X40</span><span>7 → X150</span><span>8 → X500</span><span>9 → X1000</span><span>10 → X2500</span></div></section>`,'Keno','QUICK GAME')}
function toggleKeno(n,btn){const selected=[...document.querySelectorAll('.keno-num.selected')];if(btn.classList.contains('selected'))btn.classList.remove('selected');else{if(selected.length>=10)return toast('Максимум 10 чисел');btn.classList.add('selected')}const count=document.querySelectorAll('.keno-num.selected').length;const el=$('#kenoSelected');if(el)el.textContent=`${count} / 10`}
async function playKeno(){const nums=[...document.querySelectorAll('.keno-num.selected')].map(x=>Number(x.dataset.number));if(nums.length<2)return toast('Выбери минимум 2 числа');try{const d=await api('/api/keno/play',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({numbers:nums,amount:Number($('#kenoAmount').value)})});me=d.user;sicoSound(d.payout?'win':'lose');const r=$('#kenoResult');if(r)r.innerHTML=`<div class="game-result ${d.payout?'positive':'negative'}"><b>${d.hits} совпадений</b><span>Выпали: ${d.drawn.join(', ')}</span><strong>${d.payout?`+${d.payout} SC · X${d.multiplier}`:'Ставка проиграла'}</strong></div>`;toast(d.payout?`Keno · ${d.hits} совпадений · +${d.payout} SC`:'Keno · 0 выплата')}catch(e){toast(e.message)}}

const TOWER_MULTIPLIERS=[1.2,1.5,2,3,5,10];
async function towerView(seq=currentSeq()){const d=await api('/api/tower/state').catch(()=>({game:null}));if(seq!==renderSeq||route!=='tower')return;const g=d.game;const floors=Array.from({length:6},(_,i)=>{const done=g&&i<g.floor,current=g&&i===g.floor;return `<div class="tower-row ${done?'done':''} ${current?'current':''}"><span class="tower-floor">${i+1}</span>${[0,1,2].map(c=>current?`<button class="tower-cell" onclick="towerChoose(${c})">?</button>`:`<div class="tower-cell ${done?'safe':''}">${done?'✓': '·'}</div>`).join('')}<span class="tower-mult">X${TOWER_MULTIPLIERS[i]||10}</span></div>`}).join('');shell(`<section class="card game-panel tower-scene"><div class="gamehead"><div><div class="eyebrow">CLIMB</div><h1>▥ Tower</h1><p class="muted">Одна безопасная клетка на этаж. Поднимайся или забирай.</p></div><span class="pill">${g?`X${g.multiplier}`:'START'}</span></div>${g?`<div class="tower-rows">${floors}</div><div class="actions">${g.floor?`<button class="accent" onclick="towerCashout()">Забрать ${Math.floor(g.amount*g.multiplier)} SC</button>`:''}<span class="muted">Этаж ${g.floor}/6</span></div>`:`<div class="betbar"><input id="towerAmount" class="field" type="number" min="1" value="10" placeholder="Ставка, SC"><button class="accent" onclick="towerStart()">Поднять ставку</button></div>`}</section>`,'Tower','STRATEGY GAME')}
async function towerStart(){try{const d=await api('/api/tower/start',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount:Number($('#towerAmount').value)})});me=d.user;sicoSound('bet');render('tower')}catch(e){toast(e.message)}}
async function towerChoose(choice){try{const d=await api('/api/tower/choose',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({choice})});me=d.user;sicoSound(d.win?'win':'lose');toast(d.win?`Этаж ${d.game.floor} · X${d.game.multiplier}`:'МИНА · ставка потеряна');render('tower')}catch(e){toast(e.message)}}
async function towerCashout(){try{const d=await api('/api/tower/cashout',{method:'POST',headers:{'X-Request-ID':rid()}});me=d.user;sicoSound('cashout');toast(`Забрано ${d.game.payout} SC · +${d.game.profit} SC`);render('tower')}catch(e){toast(e.message)}}

async function diceDuelView(){shell(`<section class="card game-panel duel-scene"><div class="eyebrow">VERSUS</div><h1>⚔ Dice Duel</h1><p class="muted">Два твоих кубика против двух кубиков дилера. Больше сумма — победа ×2.</p><div class="duel-board"><div><small>Ты</small><div class="dice-row"><span>?</span><span>?</span></div></div><div class="vs">VS</div><div><small>Дилер</small><div class="dice-row"><span>?</span><span>?</span></div></div></div><input id="duelAmount" class="field" type="number" min="1" value="10" placeholder="Ставка, SC"><button class="accent wide" onclick="playDiceDuel()">Бросить</button><div id="duelResult"></div></section>`,'Dice Duel','QUICK GAME')}
async function playDiceDuel(){try{const d=await api('/api/dice-duel',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount:Number($('#duelAmount').value)})});me=d.user;sicoSound(d.outcome==='won'?'win':d.outcome==='push'?'cashout':'lose');const r=$('#duelResult');if(r)r.innerHTML=`<div class="game-result ${d.outcome==='won'?'positive':d.outcome==='lost'?'negative':''}"><b>${d.player.join(' + ')} = ${d.playerTotal}</b><span>Дилер: ${d.dealer.join(' + ')} = ${d.dealerTotal}</span><strong>${d.outcome==='won'?`+${d.payout} SC` : d.outcome==='push'?'Возврат ставки':'Проигрыш'}</strong></div>`}catch(e){toast(e.message)}}

async function baccaratView(){shell(`<section class="card game-panel baccarat-scene"><div class="eyebrow">TABLE</div><h1>♣ Baccarat</h1><p class="muted">Классический выбор: Player, Banker или Tie. Banker выплачивает ×1.95.</p><div class="baccarat-actions">${gameCardButton('player','PLAYER',true)}${gameCardButton('banker','BANKER')}${gameCardButton('tie','TIE')}</div><input id="baccaratAmount" class="field" type="number" min="10" value="10" placeholder="Ставка, SC"><button class="accent wide" onclick="playBaccarat()">Сдать карты</button><div id="baccaratResult"></div></section>`,'Baccarat','TABLE GAME');window._selectedGameChoice='player'}
async function playBaccarat(){const choice=window._selectedGameChoice||'player';try{const d=await api('/api/baccarat/play',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount:Number($('#baccaratAmount').value),choice})});me=d.user;sicoSound(d.status==='won'?'win':d.status==='push'?'cashout':'lose');const r=$('#baccaratResult');if(r)r.innerHTML=`<div class="baccarat-result"><div><b>PLAYER</b><div class="cards">${d.player.map(simpleCard).join('')}</div><strong>${d.playerTotal}</strong></div><div><b>BANKER</b><div class="cards">${d.dealer.map(simpleCard).join('')}</div><strong>${d.bankerTotal}</strong></div><div class="game-result ${d.status==='won'?'positive':d.status==='lost'?'negative':''}"><b>${d.outcome.toUpperCase()}</b><span>${d.status==='won'?`+${d.payout} SC`:d.status==='push'?'Возврат ставки':'Ставка проиграла'}</span></div></div>`}catch(e){toast(e.message)}}

async function dailySpinView(seq=currentSeq()){const d=await api('/api/daily-spin').catch(()=>({available:false,rewards:[10,25,50,100,250,500]}));if(seq!==renderSeq||route!=='dailyspin')return;shell(`<section class="card game-panel daily-spin-scene"><div class="eyebrow">DAILY REWARD</div><h1>✹ Daily Spin</h1><p class="muted">Одно бесплатное вращение в день. Никаких ставок.</p><div class="daily-spin-wheel" id="dailySpinWheel"><div class="daily-spin-core">SICO</div></div><div class="spin-prizes">${d.rewards.map(x=>`<span>${x} SC</span>`).join('')}</div><button class="accent wide" id="spinBtn" ${d.available?'':'disabled'} onclick="playDailySpin()">${d.available?'Крутить бесплатно':'Уже использовано сегодня'}</button><p class="muted spin-note">Следующий спин откроется после новой календарной даты.</p></section>`,'Daily Spin','DAILY DROP')}
async function playDailySpin(){const btn=$('#spinBtn');if(btn)btn.disabled=true;try{const d=await api('/api/daily-spin',{method:'POST',headers:{'X-Request-ID':rid()}});me=d.user;sicoSound('spin');sicoHaptic('spin');const w=$('#dailySpinWheel');if(w)w.classList.add('daily-spin-running');setTimeout(()=>{if(w)w.classList.remove('daily-spin-running');toast(`🎁 Daily Spin · +${d.reward} SC`);render('dailyspin')},1800)}catch(e){if(btn)btn.disabled=false;toast(e.message)}}

async function progressionView(seq=currentSeq()){const d=await api('/api/progression');if(seq!==renderSeq||route!=='progression')return;checkLevelUp(d.level);shell(`<section class="card progression-hero"><div class="eyebrow">YOUR PROGRESSION</div><h1>Уровень ${d.level}</h1><p class="muted">${d.xp} / ${d.nextXp} XP до следующего уровня</p><div class="xp"><i style="width:${d.progress}%"></i></div></section><section class="card"><div class="section-head"><div><div class="eyebrow">QUESTS</div><h3>Задания</h3></div></div><div class="quest-grid">${d.quests.map(q=>`<div class="quest ${q.value>=q.target?'done':''}"><div><b>${esc(q.title)}</b><small>${esc(q.desc)}</small></div><strong>${Math.min(q.value,q.target)}/${q.target}</strong></div>`).join('')}</div></section><section class="card"><div class="section-head"><div><div class="eyebrow">MILESTONES</div><h3>Вехи уровня</h3></div></div><div class="milestone-grid">${d.milestones.map(m=>`<div class="milestone ${m.unlocked?'unlocked':''}"><span>${m.unlocked?'✓':'LVL '+m.level}</span><div><b>${esc(m.label)}</b><small>${esc(m.desc)}</small></div></div>`).join('')}</div></section>`,'Прогрессия','PROGRESSION')}
async function socialView(seq=currentSeq()){const d=await api('/api/social');if(seq!==renderSeq||route!=='social')return;window._social=d;shell(`<section class="card social-hero"><div><div class="eyebrow">SICO SOCIAL</div><h1>Соцсеть</h1><p class="muted">Профили, подписки, посты и общий чат — в одном месте.</p></div></section><section class="card"><div class="section-head"><div><div class="eyebrow">CREATE</div><h3>Новый пост</h3></div><span class="muted">280 символов</span></div><textarea id="socialPost" class="field social-text" maxlength="280" placeholder="Что происходит в SICO?"></textarea><button class="accent" onclick="createPost()">Опубликовать</button></section><section class="split social-split"><div class="card"><div class="section-head"><div><div class="eyebrow">FEED</div><h3>Лента</h3></div></div><div id="socialFeed" class="feed">${d.posts.map(postHtml).join('')||'<p class="muted">Лента пока пустая.</p>'}</div></div><div class="card"><div class="section-head"><div><div class="eyebrow">PEOPLE</div><h3>Игроки</h3></div></div><div class="feed">${d.people.map(p=>`<div class="person"><div onclick="showPlayer('${p.id}')" class="grow player-click">${avatar(p)}<b>${esc(p.login)}</b><small>LVL ${p.level}${p.title?' · '+esc(p.title):''}</small></div><button class="ghost" onclick="toggleFollow('${p.id}',this)">${p.following?'Отписаться':'Подписаться'}</button></div>`).join('')||'<p class="muted">Пока никого нет.</p>'}</div></div></section>`,'Соцсеть','SOCIAL NETWORK')}
function postHtml(p){return `<article class="social-post" id="post-${p.id}"><div class="person"><div class="grow player-click" onclick="showPlayer('${p.author.id}')">${avatar(p.author)}<b>${esc(p.author.login)}</b><small>LVL ${p.author.level} · ${new Date(p.at).toLocaleString()}</small></div></div><p>${esc(p.text)}</p><button class="ghost post-like" onclick="likePost('${p.id}',this)">${p.liked?'♥':'♡'} ${p.likes}</button></article>`}
async function createPost(){const el=$('#socialPost');if(!el?.value.trim())return toast('Напиши что-нибудь');try{await api('/api/social/posts',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({text:el.value})});render('social')}catch(e){toast(e.message)}}
async function toggleFollow(id,btn){try{const d=await api('/api/social/follow/'+id,{method:'POST',headers:{'X-Request-ID':rid()}});btn.textContent=d.following?'Отписаться':'Подписаться'}catch(e){toast(e.message)}}
async function likePost(id,btn){try{const d=await api('/api/social/posts/'+id+'/like',{method:'POST',headers:{'X-Request-ID':rid()}});btn.textContent=(d.liked?'♥':'♡')+' '+d.likes}catch(e){toast(e.message)}}
async function redeemPromo(){const code=$('#redeemPromoCode')?.value.trim();if(!code)return toast('Введи промокод');try{const d=await api('/api/promocodes/redeem',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({code})});if(d.user)me=d.user;toast(d.message||'Промокод активирован');$('#redeemPromoCode').value=''}catch(e){toast(e.message)}}
function moreView(){shell(`<section class="card"><div class="eyebrow">SICO MENU</div><h1>☰ Ещё</h1><p class="muted">Дополнительные разделы аккаунта и проекта.</p></section><section class="card"><h3>Активировать промокод</h3><p class="muted">Введи код из официального Telegram-канала.</p><div class="admin-search"><input id="redeemPromoCode" class="field" maxlength="40" placeholder="ПРОМОКОД"><button class="accent" onclick="redeemPromo()">Активировать</button></div></section><section class="more-grid">${[['cases','◇','Кейсы'],['bank','₿','Банк'],['inventory','🎒','Инвентарь'],['leaderboard','🏆','Лидерборд'],['achievements','✦','Достижения'],['progression','⚡','Прогрессия'],['history','↺','История'],['security','🔐','Безопасность'],['extras','💬','Чат'],['rules','ⓘ','Правила'],...(adminToken?[['admin','♛','Админка']]:[])].map(x=>`<button class="card more-item" onclick="render('${x[0]}')"><span>${x[1]}</span><b>${x[2]}</b><small>Открыть →</small></button>`).join('')}</section>`,'Ещё','SICO MENU')}
function cardLabel(c){const r=c%13;return `${r===0?'A':r===10?'J':r===11?'Q':r===12?'K':r+1}${['♠','♥','♦','♣'][Math.floor(c/13)]}`}
async function blackjackView(seq=currentSeq()){
  const d=await api('/api/blackjack').catch(()=>({game:null}));
  if(seq!==renderSeq||route!=='blackjack')return;
  const g=d.game;
  const resultCard=g&&g.state!=='playing'?`<section class="card bj-result ${g.state}">
    <div class="eyebrow">РАСЧЁТ РАУНДА</div>
    <div class="bj-result-grid">
      <div><span>Ставка</span><b>${Number(g.amount).toLocaleString()} SC</b></div>
      <div><span>Выплата</span><b>${Number(g.payout||0).toLocaleString()} SC</b></div>
      <div><span>Чистый результат</span><b class="${g.profit>0?'positive':g.profit<0?'negative':''}">${g.profit>0?'+':''}${Number(g.profit||0).toLocaleString()} SC</b></div>
      <div><span>Баланс</span><b>${Number(g.balanceAfter??me.balance).toLocaleString()} SC</b></div>
    </div>
    <p class="muted">${g.state==='won'?'Победа: ставка возвращена в составе выплаты ×2.00.':g.state==='blackjack'?'Натуральный Blackjack: выплата ×2.50.':g.state==='push'?'Ничья: возвращена только исходная ставка.':'Проигрыш: ставка списана.'}</p>
    <button class="accent wide" onclick="render('blackjack')">Новая раздача</button>
  </section>`:'';
  shell(`<section class="card game-panel blackjack blackjack-scene"><div class="eyebrow">TABLE GAME</div><div class="bj-headline"><div><h1>♠ Blackjack</h1><p class="muted">Победа ×2.00 от суммы ставки. Натуральный Blackjack ×2.50.</p></div><div class="pill">HOUSE TABLE</div></div><div class="bj-rules-strip"><span>🃏 Дилер стоит на 17</span><span>♠ Blackjack ×2.50</span><span>🎯 Победа ×2.00</span></div><div class="blackjack-table"><div><small>Дилер</small><div class="cards">${g?(g.state==='playing'?cardHtml(g.dealer[0])+'<div class="playing-card hidden-card">?</div>':g.dealer.map(cardHtml).join('')):'—'}</div><b>${g&&g.state!=='playing'?handValueClient(g.dealer):g?'?':' '}</b></div><div><small>Ты</small><div class="cards">${g?g.player.map(cardHtml).join(''):'—'}</div><b>${g?handValueClient(g.player):' '}</b></div></div>${g&&g.state==='playing'?`<div class="actions"><button class="accent" onclick="bjHit()">Hit</button><button class="ghost" onclick="bjStand()">Stand</button></div>`:!g?`<div class="betbar"><div class="bj-chip-row">${[10,25,50,100,250].map(v=>`<button class="ghost" onclick="$('#bjAmount').value='${v}'">${v}</button>`).join('')}</div><input id="bjAmount" class="field" type="number" min="1" placeholder="Ставка, SC"><button class="accent" onclick="bjStart()">Начать</button></div>`:''}</section>${resultCard}`,'Blackjack','GAME CENTER')
}
function cardHtml(c){return `<span class="playing-card">${esc(cardLabel(c))}</span>`}
function handValueClient(h){let v=0,a=0;for(const c of h){const r=c%13;v+=r===0?11:r>=10?10:r+1;if(r===0)a++}while(v>21&&a--)v-=10;return v}
async function bjStart(){try{const d=await api('/api/blackjack/start',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount:Number($('#bjAmount').value)})});me=d.user;sicoSound('bet');render('blackjack')}catch(e){toast(e.message)}}
async function bjHit(){try{const d=await api('/api/blackjack/hit',{method:'POST',headers:{'X-Request-ID':rid()}});me=d.user;sicoSound(d.game?.state==='won'||d.game?.state==='blackjack'?'win':d.game?.state==='lost'?'lose':'reveal');render('blackjack')}catch(e){toast(e.message)}}
async function bjStand(){try{const d=await api('/api/blackjack/stand',{method:'POST',headers:{'X-Request-ID':rid()}});me=d.user;sicoSound(d.game?.state==='won'||d.game?.state==='blackjack'?'win':d.game?.state==='lost'?'lose':'reveal');render('blackjack')}catch(e){toast(e.message)}}
async function minesView(seq=currentSeq()){const d=await api('/api/mines/state').catch(()=>({game:null}));if(seq!==renderSeq||route!=='mines')return;const g=d.game;shell(`<section class="card game-panel mines-scene"><div class="eyebrow">NEW GAME</div><h1>✦ Mines</h1><p class="muted">Выбери число мин, открывай клетки и забирай выплату до мины.</p>${g?`<div class="mines-meta"><span>Множитель <b>${g.multiplier}x</b></span><button class="accent" onclick="minesCashout()">Забрать ${Math.floor(g.amount*g.multiplier)} SC</button></div><div class="mines-grid">${Array.from({length:25},(_,i)=>`<button class="mine-cell ${g.opened.includes(i)?'opened':''} ${g.revealed&&g.mines?.includes(i)?'mine':''}" onclick="mineOpen(${i})">${g.opened.includes(i)?'✓':g.revealed&&g.mines?.includes(i)?'✦':''}</button>`).join('')}</div>`:`<div class="betbar"><input id="minesAmount" class="field" type="number" min="1" placeholder="Ставка, SC"><select id="minesCount" class="field"><option value="3">3 мины</option><option value="5">5 мин</option><option value="8">8 мин</option><option value="12">12 мин</option></select><button class="accent" onclick="minesStart()">Начать</button></div>`}</section>`,'Mines','GAME CENTER')}
async function minesStart(){try{const d=await api('/api/mines/start',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount:Number($('#minesAmount').value),mines:Number($('#minesCount').value)})});me=d.user;render('mines')}catch(e){toast(e.message)}}
async function mineOpen(cell){try{const d=await api('/api/mines/open',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({cell})});me=d.user;sicoSound(d.game?.state==='lost'?'lose':d.game?.state==='won'?'win':'reveal');render('mines')}catch(e){toast(e.message)}}
async function minesCashout(){try{const d=await api('/api/mines/cashout',{method:'POST',headers:{'X-Request-ID':rid()}});me=d.user;sicoSound('cashout');toast(`+${d.game.payout} SC`);render('mines')}catch(e){toast(e.message)}}
async function diceView(){shell(`<section class="card game-panel dice-panel dice-scene"><div class="eyebrow">NEW GAME</div><h1>🎲 Dice</h1><p class="muted">Выбери вероятность. Выплата рассчитывается сервером.</p><div class="dice-result" id="diceResult">—</div><input id="diceAmount" class="field" type="number" min="1" placeholder="Ставка, SC"><div class="dice-controls"><label>Шанс <input id="diceChance" class="field" type="number" min="2" max="98" value="50"></label><label>Условие <select id="diceSide" class="field"><option value="over">Бросок выше порога</option><option value="under">Бросок ниже порога</option></select></label></div><button class="accent wide" onclick="playDice()">Бросить</button></section>`,'Dice','GAME CENTER')}
async function playDice(){try{const d=await api('/api/dice',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount:Number($('#diceAmount').value),chance:Number($('#diceChance').value),side:$('#diceSide').value})});me=d.user;const r=$('#diceResult');if(r)r.textContent=`${d.roll} · ${d.win?'WIN +'+d.payout+' SC':'LOSS'}`;sicoSound(d.win?'win':'lose')}catch(e){toast(e.message)}}
async function securityView(seq=currentSeq()){const [s2,ses]=await Promise.all([api('/api/security/2fa'),api('/api/security/sessions')]);if(seq!==renderSeq||route!=='security')return;window._securitySessions=ses.sessions;shell(`<section class="card"><div class="eyebrow">ACCOUNT SECURITY</div><h1>🔐 Безопасность</h1><p class="muted">Управляй 2FA, паролем и активными устройствами.</p></section><section class="card"><div class="section-head"><div><div class="eyebrow">TWO-FACTOR AUTH</div><h3>2FA</h3></div><span class="pill ${s2.enabled?'security-on':''}">${s2.enabled?'Включена':'Выключена'}</span></div>${s2.enabled?`<p class="muted">Для входа нужен код из Authenticator. Отключение требует текущего кода.</p><div class="security-inline"><input id="disable2faCode" class="field" inputmode="numeric" maxlength="6" placeholder="Код 2FA"><button class="danger" onclick="disable2fa()">Отключить 2FA</button></div>`:`<p class="muted">Подключи Authenticator. Сейчас покажем секрет и ссылку, которую можно импортировать вручную.</p><button class="accent" onclick="setup2fa()">Настроить 2FA</button><div id="twoFactorSetup"></div>`}</section><section class="card"><div class="section-head"><div><div class="eyebrow">PASSWORD</div><h3>Смена пароля</h3></div></div><input id="currentPassword" class="field" type="password" placeholder="Текущий пароль"><input id="newPassword" class="field" type="password" placeholder="Новый пароль"><input id="newPassword2" class="field" type="password" placeholder="Повтори новый пароль">${s2.enabled?'<input id="password2fa" class="field" inputmode="numeric" maxlength="6" placeholder="Код 2FA">':''}<button class="accent" onclick="changePassword()">Изменить пароль</button></section><section class="card"><div class="section-head"><div><div class="eyebrow">FEEDBACK</div><h3>Звук и вибрация</h3></div></div><div class="row"><span>Звуки интерфейса</span><button class="ghost" onclick="sicoSoundSettings(!soundEnabled,hapticsEnabled);render('security')">${soundEnabled?'Вкл.':'Выкл.'}</button></div><div class="row"><span>Виброотклик</span><button class="ghost" onclick="sicoSoundSettings(soundEnabled,!hapticsEnabled);sicoHaptic('success');render('security')">${hapticsEnabled?'Вкл.':'Выкл.'}</button></div></section><section class="card"><div class="section-head"><div><div class="eyebrow">ACTIVE SESSIONS</div><h3>Сессии</h3></div><button class="ghost" onclick="logoutOtherSessions()">Завершить остальные</button></div><div class="feed">${ses.sessions.map(x=>`<div class="person session-row"><div class="grow"><b>${x.current?'Это устройство':'Активная сессия'}</b><small>${x.device?'Device '+esc(x.device.slice(0,18)):'Неизвестное устройство'} · ${new Date(x.createdAt).toLocaleString()}${x.ip?' · '+esc(x.ip):''}</small></div>${x.current?'<span class="pill">Текущая</span>':`<button class="danger" onclick="killSession('${x.id}')">Завершить</button>`}</div>`).join('')||'<p class="muted">Активных сессий нет.</p>'}</div></section>`,'Безопасность','ACCOUNT SECURITY')}
async function setup2fa(){try{const d=await api('/api/security/2fa/setup',{method:'POST',headers:{'X-Request-ID':rid()}});const el=$('#twoFactorSetup');if(el)el.innerHTML=`<div class="twofactor-box"><b>Секрет</b><code>${esc(d.secret)}</code><small>Добавь его в Authenticator вручную. URI:</small><textarea class="field" readonly>${esc(d.otpauth)}</textarea><input id="enable2faCode" class="field" inputmode="numeric" maxlength="6" placeholder="Код из Authenticator"><button class="accent" onclick="enable2fa()">Подтвердить и включить</button></div>`}catch(e){toast(e.message)}}
async function enable2fa(){try{await api('/api/security/2fa/enable',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({code:$('#enable2faCode').value})});toast('2FA включена');render('security')}catch(e){toast(e.message)}}
async function disable2fa(){try{await api('/api/security/2fa/disable',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({code:$('#disable2faCode').value})});toast('2FA отключена');render('security')}catch(e){toast(e.message)}}
async function changePassword(){const a=$('#currentPassword').value,b=$('#newPassword').value,c=$('#newPassword2').value;if(b!==c)return toast('Новые пароли не совпадают');try{await api('/api/security/password',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({currentPassword:a,newPassword:b,code:$('#password2fa')?.value||''})});toast('Пароль изменён. Остальные сессии завершены.');render('security')}catch(e){toast(e.message)}}
async function killSession(id){try{await api('/api/security/sessions/'+id,{method:'DELETE'});render('security')}catch(e){toast(e.message)}}
async function logoutOtherSessions(){try{await api('/api/security/sessions/logout-others',{method:'POST',headers:{'X-Request-ID':rid()}});toast('Остальные сессии завершены');render('security')}catch(e){toast(e.message)}}
function coinFlipView(){shell(`<section class="card coin-panel coin-scene"><div class="eyebrow">50 / 50</div><h1>Coin Flip</h1><p class="muted">Орёл или решка. Победа возвращает ставку ×2.</p><div class="coin">S</div><div class="coin-result" id="coinResult">Готов?</div><input id="coinAmount" class="field" type="number" min="1" placeholder="Ставка, SC"><button class="accent wide" onclick="playCoinFlip()">Подбросить монетку</button></section>`,'Coin Flip','MINI GAME')}
async function playCoinFlip(){if(window.coinBusy)return;window.coinBusy=true;try{const amount=Math.floor(Number($('#coinAmount').value));const d=await api('/api/coinflip',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount})});me=d.user;const c=document.querySelector('.coin');c?.classList.add('coin-flip');setTimeout(()=>c?.classList.remove('coin-flip'),900);setTimeout(()=>{const r=$('#coinResult');if(r)r.textContent=d.win?`🎉 ${d.side} · +${d.payout} SC`:`${d.side} · -${amount} SC`;sicoSound(d.win?'win':'lose')},420)}catch(e){toast(e.message)}finally{setTimeout(()=>window.coinBusy=false,950)}}
async function showPlayer(id){try{const d=await api('/api/player/'+id);const p=d.player;const ov=document.createElement('div');ov.className='case-overlay player-overlay';const v=p.visibility||{};const field=(label,val,visible=true)=>visible?`<div class="stat"><span>${label}</span><b>${val}</b></div>`:`<div class="stat"><span>${label}</span><b class="muted">Скрыто</b></div>`;const avObj=p.avatar&&typeof p.avatar==='object'?p.avatar:null;const publicAvatar=avObj?`<div class="bigavatar">${esc(avObj.icon||'?')}</div>`:p.avatar?`<img class="bigavatar" src="${p.avatar}">`:`<div class="bigavatar">${esc((p.login||'?')[0]).toUpperCase()}</div>`;ov.innerHTML=`<div class="case-result player-card-modal">${publicAvatar}<div class="eyebrow">PLAYER PROFILE</div><h2>${esc(p.login)}</h2><p class="muted">${p.status===null?'':esc(p.status||'')}</p>${p.title?`<span class="profile-title-chip">${esc(p.title)}</span>`:''}<div class="stats">${field('Уровень',p.level??'—',v.level!==false)}${field('XP',p.xp??'—',v.xp!==false)}${field('Игры',p.stats?.games??'—',v.stats!==false)}${field('Победы',p.stats?.won??'—',v.stats!==false)}${field('Лучший выигрыш',(p.stats?.biggestWin??0)+' SC',v.stats!==false)}${field('Trading P/L',p.trading?((Number(p.trading.pnl)>=0?'+':'')+Number(p.trading.pnl).toLocaleString()+' SC'):'—',v.trading!==false)}${field('SCoin',p.trading?(Number(p.trading.scCoin).toFixed(2)):'—',v.trading!==false)}${field('Достижения',p.badgesCount??0,v.achievements!==false)}${field('Дата регистрации',p.createdAt?new Date(p.createdAt).toLocaleDateString():'—',v.createdAt!==false)}</div><button class="ghost wide">Закрыть</button>${p.id&&p.id!==me?.id?`<button class="ghost wide rp-link" data-login="${esc(p.login)}" onclick="reportPlayer('${p.id}',this.dataset.login)">⚑ Пожаловаться</button>`:''}</div>`;document.body.append(ov);ov.onclick=e=>{if(e.target===ov)ov.remove()};ov.querySelector('button').onclick=()=>ov.remove()}catch(e){toast(e.message)}}
async function bankDeposit(){try{const amount=Math.floor(Number($('#bankAmount').value));const d=await api('/api/bank/deposit',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':rid()},body:JSON.stringify({amount})});me=d.user;toast(`В банк положено ${amount} SC`);render('profile')}catch(e){toast(e.message)}}
async function bankWithdraw(){try{const d=await api('/api/bank/withdraw',{method:'POST',headers:{'X-Request-ID':rid()}});me=d.user;sicoSound('win');toast(`Банк вернул ${d.payout} SC`);render('profile')}catch(e){toast(e.message)}}

function chatMsg(m){const rep=(!m.system&&m.userId&&m.id&&me&&m.userId!==me.id)?`<button class="chat-report" title="Пожаловаться" aria-label="Пожаловаться" data-login="${esc(m.login)}" onclick="reportMessage('${m.id}',this.dataset.login)">⚑</button>`:'';return `<div class="chat-msg ${m.system?'system-msg':''}">${avatar({login:m.login})}<div><b>${esc(m.login)}</b><p>${esc(m.text)}</p><small>${new Date(m.at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</small></div>${rep}</div>`}
const REPORT_REASONS_UI=[['spam','Спам / флуд'],['abuse','Оскорбления'],['scam','Мошенничество'],['exploit','Баг / эксплойт'],['other','Другое']];
function reportMessage(messageId,login){reportDialog({messageId},login,'Сообщение игрока')}
function reportPlayer(targetId,login){reportDialog({targetId},login,'Профиль игрока')}
function reportDialog(payload,login,what){
  document.querySelector('.rp-overlay')?.remove();
  const ov=document.createElement('div');ov.className='case-overlay rp-overlay';
  ov.innerHTML=`<div class="case-result rp-modal"><div class="eyebrow">ЖАЛОБА</div><h2>${esc(login||'Игрок')}</h2><p class="muted">${esc(what||'')}. Администрация проверит жалобу. Ложные жалобы могут привести к ограничениям.</p><label>Причина</label><select id="rpReason" class="field">${REPORT_REASONS_UI.map(r=>`<option value="${r[0]}">${r[1]}</option>`).join('')}</select><label>Комментарий (необязательно)</label><textarea id="rpText" class="field" rows="3" maxlength="300" placeholder="Что случилось?"></textarea><div class="rp-actions"><button class="ghost" id="rpCancel">Отмена</button><button class="accent" id="rpSend">Отправить</button></div></div>`;
  document.body.append(ov);
  ov.onclick=e=>{if(e.target===ov)ov.remove()};
  ov.querySelector('#rpCancel').onclick=()=>ov.remove();
  ov.querySelector('#rpSend').onclick=async e=>{
    const btn=e.currentTarget;btn.disabled=true;
    try{await api('/api/report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,reason:ov.querySelector('#rpReason').value,text:ov.querySelector('#rpText').value.trim()})});toast('Жалоба отправлена');ov.remove()}
    catch(err){toast(err.message);btn.disabled=false}
  };
}
async function rulesView(){shell(`<section class="card"><div class="eyebrow">SICO COMMUNITY</div><h3>Правила пользования</h3><div class="feed"><div class="row"><b>1. Общение</b><span>Без оскорблений, травли, спама и токсичного поведения.</span></div><div class="row"><b>2. Игры</b><span>Используй только честную игру. Баги и уязвимости нельзя эксплуатировать.</span></div><div class="row"><b>3. Баги</b><span>Нашёл ошибку — сообщи владельцу SICO, а не используй её для получения SC.</span></div><div class="row"><b>4. Чат</b><span>Максимум 1 сообщение в 5 секунд. Лимит истории — 30 сообщений.</span></div><div class="row"><b>5. Модерация</b><span>За нарушения администрация может ограничить чат или заблокировать аккаунт.</span></div></div></section><section class="card"><h3>Важно</h3><p class="muted">SICO — локальная игра с виртуальными SC. SC не являются реальными деньгами и не выводятся.</p></section>`,'Правила пользования','COMMUNITY RULES')}
