const apI=(n,s=18)=>`<svg class="ap-i" width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${AP_ICONS[n]||''}</svg>`;
const AP_TABS=[['dashboard','dashboard','Обзор'],['players','players','Игроки'],['economy','economy','Экономика'],['promocodes','promocodes','Промокоды'],['content','content','Контент'],['moderation','moderation','Модерация'],['logs','logs','Журнал'],['live','live','Live Monitor'],['reports','reports','Жалобы'],['rewards','rewards','Выдача наград'],['announcements','announcements','Объявления'],['events','events','Ивенты'],['diagnostics','diagnostics','Диагностика'],['settings','settings','Система']];
const apFmt=n=>{n=Number(n)||0;const a=Math.abs(n),f=(v,u)=>(Math.abs(v)>=100?Math.round(v):Math.round(v*10)/10)+u;if(a>=1e9)return f(n/1e9,'B');if(a>=1e6)return f(n/1e6,'M');if(a>=1e4)return f(n/1e3,'K');return n.toLocaleString('ru-RU')};
const apTime=at=>{const d=new Date(at||Date.now()),now=new Date();return d.toDateString()===now.toDateString()?d.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):d.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit'})+' '+d.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})};
async function renderAdminTab(tab='dashboard'){
  adminTab=tab;
  let body;
  try{body=await adminTabContent(tab)}catch(e){toast(e.message||'Не удалось загрузить раздел');return}
  if(route!=='admin')return;
  document.body.dataset.route='admin';
  document.body.dataset.theme=me?.theme||'graphite';
  const cur=AP_TABS.find(t=>t[0]===tab)||AP_TABS[0];
  const nb=t=>`<button class="ap-nav ${tab===t[0]?'active':''}" title="${t[2]}" aria-label="${t[2]}" onclick="renderAdminTab('${t[0]}')">${apI(t[1])}</button>`;
  const main=AP_TABS.filter(t=>t[0]!=='settings').map(nb).join(''),set=nb(AP_TABS.find(t=>t[0]==='settings'));
  app.innerHTML=`<div class="ap-wrap"><div class="ap"><header class="ap-top"><div class="ap-logo">${apI('shield',20)}</div><div class="ap-title"><b>Admin Panel</b><span>${cur[2]}</span></div><div class="ap-pill"><i></i>${state.online||0}</div><div class="ap-win"><button class="ap-ib" title="Обновить" aria-label="Обновить" onclick="renderAdminTab(adminTab)">${apI('refresh',15)}</button><button class="ap-ib" title="Закрыть панель" aria-label="Закрыть панель" onclick="render('home')">${apI('close',16)}</button></div></header><nav class="ap-rail">${main}<span class="ap-rail-gap"></span>${set}<button class="ap-nav ap-nav-exit" title="Выйти из админки" aria-label="Выйти из админки" onclick="adminLogout()">${apI('logout')}</button></nav><main class="ap-main" id="apMain">${body}</main></div></div>`;
}
async function apAllUsers(){let all=[],page=1,total=0;do{const d=await adminFetch(`/api/admin/users?limit=100&page=${page}`);all=all.concat(d.users||[]);total=d.total||0;page++}while(all.length<total&&page<=10);return all}
function apDonut(segs,icon,color){const tot=segs.reduce((n,s)=>n+s.v,0),live=segs.filter(s=>s.v>0),gap=live.length>1?1.6:0;let off=0;const arcs=tot>0?live.map(s=>{const l=s.v/tot*100,len=Math.max(l-gap,.4),el=`<circle cx="23" cy="23" r="19" pathLength="100" fill="none" stroke="${s.c}" stroke-width="3.2" stroke-dasharray="${len} ${100-len}" stroke-dashoffset="${-off}" transform="rotate(-90 23 23)"/>`;off+=l;return el}).join(''):'';return `<div class="ap-ring" style="color:${color}"><svg width="46" height="46" viewBox="0 0 46 46"><circle cx="23" cy="23" r="19" fill="none" stroke="#1f1f24" stroke-width="3.2"/>${arcs}</svg><i>${apI(icon,17)}</i></div>`}
function apLeg(c,label,val,pct,sq){return `<div class="ap-leg"><i class="${sq?'sq':''}" style="background:${c}"></i><span>${label}</span><em>${val}${pct!=null?`<s>${pct}%</s>`:''}</em></div>`}
const AP_COLORS=['#3b82f6','#ef4444','#f59e0b','#eab308','#a855f7','#22c55e'];
function apTop(mode='all'){
  const box=$('#apTopList');if(!box||!window.__apTop)return;
  const {users,online}=window.__apTop;
  document.querySelectorAll('#apTopSeg button').forEach(b=>b.classList.toggle('on',b.dataset.m===mode));
  const rows=(mode==='online'?users.filter(u=>online.has(u.id)):users).slice(0,6),max=Math.max(1,...rows.map(u=>Number(u.balance)||0));
  box.innerHTML=rows.map((u,i)=>{const c=AP_COLORS[i%AP_COLORS.length],w=Math.max(2,Math.round((Number(u.balance)||0)/max*100));return `<div class="ap-top-row" onclick="adminPlayer('${u.id}')"><span class="ap-top-name" style="--c:${c}">${apI('user',14)}<b>${esc(u.login)}</b></span><span class="ap-bar"><i style="width:${w}%;background:${c}"></i></span><span class="ap-top-val">${apFmt(u.balance)} SC</span></div>`}).join('')||`<div class="ap-empty">${mode==='online'?'Сейчас никого нет онлайн':'Игроков пока нет'}</div>`;
}
function apAct(kind='all'){
  const box=$('#apActList');if(!box||!window.__apAct)return;
  document.querySelectorAll('#apActSeg button').forEach(b=>b.classList.toggle('on',b.dataset.k===kind));
  const rows=window.__apAct.filter(x=>kind==='all'||x.k===kind).slice(0,10);
  box.innerHTML=rows.map(x=>`<div class="ap-act"><i style="background:${x.c}"></i><span class="ap-act-t">${x.h}</span><time>${apTime(x.at)}</time></div>`).join('')||'<div class="ap-empty">Пока ничего не происходило</div>';
}
async function adminTabContent(tab){
  if(tab==='dashboard')return adminDashboard();
  if(tab==='players')return adminPlayers();
  if(tab==='economy')return adminEconomy();
  if(tab==='promocodes')return adminPromocodes();
  if(tab==='content')return adminContent();
  if(tab==='moderation')return adminModeration();
  if(tab==='logs')return adminLogs();
  if(tab==='live')return adminLive();
  if(tab==='reports')return adminReports();
  if(tab==='rewards')return adminRewards();
  if(tab==='announcements')return adminAnnouncements();
  if(tab==='events')return adminEvents();
  if(tab==='diagnostics')return adminDiagnostics();
  return adminSettings();
}
async function adminDashboard(){
  const [d,live,rep,ev,txd,users]=await Promise.all([
    adminFetch('/api/admin/overview'),
    adminFetch('/api/admin/live'),
    adminFetch('/api/admin/reports').catch(()=>({reports:[]})),
    adminFetch('/api/admin/events').catch(()=>({events:[]})),
    adminFetch('/api/admin/transactions?limit=200').catch(()=>({transactions:[]})),
    apAllUsers().catch(()=>[])
  ]);
  const online=live.active.length,openReports=(rep.reports||[]).filter(r=>r.status!=='resolved'),activeEvents=(ev.events||[]).filter(e=>e.active).length;
  const tx=txd.transactions||[],inc=tx.reduce((n,t)=>n+(Number(t.delta)>0?Number(t.delta):0),0),out=tx.reduce((n,t)=>n+(Number(t.delta)<0?-Number(t.delta):0),0),flow=inc+out||1;
  const offline=Math.max(0,d.players-d.banned-online),sessInactive=Math.max(0,live.totalSessions-online);
  window.__apTop={users:users.slice().sort((a,b)=>(Number(b.balance)||0)-(Number(a.balance)||0)),online:new Set(live.active.map(x=>x.user.id))};
  const acts=[];
  (live.recentChat||[]).forEach(m=>acts.push({k:'chat',c:'#3b82f6',at:m.at,h:`<b>${esc(m.login||'SICO')}</b> ${esc(String(m.text||'').slice(0,80))}`}));
  (live.recentTransactions||[]).forEach(t=>{const dl=Number(t.delta)||0;acts.push({k:'tx',c:dl>=0?'#22c55e':'#f59e0b',at:t.at,h:`<b>${esc(t.login||'Игрок')}</b> ${esc(typeof typeName==='function'?typeName(t.type):(t.type||'операция'))} <b>${dl>=0?'+':''}${dl.toLocaleString('ru-RU')} SC</b>`})});
  openReports.slice(0,10).forEach(r=>acts.push({k:'rep',c:'#ef4444',at:r.at||r.createdAt,h:`<b>${esc(r.reporterLogin||r.reporter||'Игрок')}</b> отправил жалобу <b>${esc(r.subject||r.type||'')}</b>`}));
  window.__apAct=acts.sort((a,b)=>(b.at||0)-(a.at||0));
  setTimeout(()=>{apTop('all');apAct('all')},0);
  return `<section class="ap-stats">
    <div class="ap-stat"><span style="color:#3b82f6">${apI('players',13)}ВСЕГО ИГРОКОВ</span><b>${Number(d.players).toLocaleString('ru-RU')}</b></div>
    <div class="ap-stat"><span style="color:#22c55e">${apI('live',13)}ОНЛАЙН СЕЙЧАС</span><b>${online}</b></div>
    <div class="ap-stat"><span style="color:#a855f7">${apI('calendar',13)}АКТИВНЫЕ ИВЕНТЫ</span><b>${activeEvents}</b></div>
    <div class="ap-stat"><span style="color:#f59e0b">${apI('ticket',13)}ЖАЛОБЫ</span><b>${openReports.length}</b></div>
  </section>
  <section class="ap-donuts">
    <div class="ap-dcard"><div class="ap-dhead">${apDonut([{v:inc,c:'#22c55e'},{v:out,c:'#3b82f6'}],'dollar','#22c55e')}<div><small>Экономика</small><b>${apFmt(d.scInCirculation)} SC</b></div></div>
      ${apLeg('#22c55e','Приход',apFmt(inc)+' SC',Math.round(inc/flow*100))}${apLeg('#3b82f6','Расход',apFmt(out)+' SC',Math.round(out/flow*100),1)}${apLeg('#6b7280','Операций за 24ч',Number(d.transactions24h).toLocaleString('ru-RU'))}</div>
    <div class="ap-dcard"><div class="ap-dhead">${apDonut([{v:online,c:'#22c55e'},{v:offline,c:'#6b7280'},{v:d.banned,c:'#ef4444'}],'players','#22c55e')}<div><small>Игроки</small><b>${Number(d.players).toLocaleString('ru-RU')}</b></div></div>
      ${apLeg('#22c55e','Онлайн',online)}${apLeg('#6b7280','Офлайн',offline)}${apLeg('#ef4444','Заблокированы',d.banned)}</div>
    <div class="ap-dcard"><div class="ap-dhead">${apDonut([{v:online,c:'#3b82f6'},{v:sessInactive,c:'#6b7280'}],'shield','#3b82f6')}<div><small>Сессии</small><b>${online}/${live.totalSessions}</b></div></div>
      ${apLeg('#3b82f6','Активные',online)}${apLeg('#6b7280','Неактивные',sessInactive)}${apLeg('#a855f7','Объём за 24ч',apFmt(d.volume24h)+' SC')}</div>
  </section>
  <section class="ap-panels">
    <div class="ap-panel"><div class="ap-phead"><b>Топ игроков</b><span class="ap-count">${Math.min(6,users.length)}</span><div class="ap-seg" id="apTopSeg"><button class="on" data-m="all" onclick="apTop('all')">Все</button><button data-m="online" onclick="apTop('online')">Онлайн</button></div></div><div id="apTopList" class="ap-list"></div></div>
    <div class="ap-panel"><div class="ap-phead"><b>Активность</b><div class="ap-seg" id="apActSeg"><button class="on" data-k="all" onclick="apAct('all')">Все</button><button data-k="chat" onclick="apAct('chat')">Чат</button><button data-k="tx" onclick="apAct('tx')">Операции</button><button data-k="rep" onclick="apAct('rep')">Жалобы</button></div></div><div id="apActList" class="ap-list"></div><button class="ap-all" onclick="renderAdminTab('live')">Показать всё ${apI('chevron',12)}</button></div>
  </section>`;
}
async function adminPlayers(){const d=await adminFetch('/api/admin/users?q='+encodeURIComponent(adminUserSearch)+'&limit=60');return `<div class="admin-head"><div><div class="eyebrow">PLAYERS</div><h1>Игроки</h1><p class="muted">Поиск, безопасность, баланс и модерация.</p></div><button class="ghost ap-csv" onclick="adminExport('players')">${apI('download',14)} CSV</button></div><section class="card"><div class="admin-search"><input id="adminUserSearch" class="field" value="${esc(adminUserSearch)}" placeholder="Логин или ID"><button class="accent" onclick="adminUserSearch=$('#adminUserSearch').value.trim();renderAdminTab('players')">Найти</button></div><div class="admin-table"><div class="admin-tr admin-th"><span>Игрок</span><span>Баланс</span><span>Уровень</span><span>Безопасность</span><span></span></div>${d.users.map(u=>`<div class="admin-tr"><span><b>${esc(u.login)}</b><small>${esc(u.id)}</small></span><span>${Number(u.balance).toLocaleString()} SC</span><span>LVL ${u.level}</span><span>${u.banned?'<i class="badge-danger">BAN</i>':'<i class="badge-ok">OK</i>'} ${u.twoFactor?'· 2FA':''} ${u.mutedUntil?'<i class="badge-warn">MUTE</i>':''}</span><span><button class="ghost" onclick="adminPlayer('${u.id}')">Открыть</button></span></div>`).join('')||'<p class="muted">Ничего не найдено.</p>'}</div><small class="muted">Найдено: ${d.total}</small></section>`}
async function adminPromocodes(){const d=await adminFetch('/api/admin/promocodes');const promos=d.promocodes||[];return `<div class="admin-head"><div><div class="eyebrow">REWARDS</div><h1>Промокоды</h1><p class="muted">Создание кодов для Telegram-канала и управление лимитами активаций.</p></div></div><section class="card"><h3>Создать промокод</h3><div class="admin-grid-2"><div><label>Код</label><input id="promoCode" class="field" maxlength="40" placeholder="TELEGRAM2026"></div><div><label>Тип награды</label><select id="promoReward" class="field" onchange="promoRewardChanged()"><option value="sc">Валюта SC</option><option value="xp">Дополнительные XP</option><option value="case">Кейс</option></select></div><div id="promoAmountWrap"><label>Количество</label><input id="promoAmount" class="field" type="number" min="1" max="100000000" value="500"></div><div id="promoCaseWrap" style="display:none"><label>Кейс</label><select id="promoCase" class="field"><option>Moon</option><option>Nova</option><option>Black</option><option>Vault</option><option>Autumn</option></select></div><div><label>Максимум активаций на всех игроков</label><input id="promoLimit" class="field" type="number" min="1" max="1000000" value="100"></div></div><button class="accent" onclick="adminCreatePromo()">Создать промокод</button></section><section class="card"><h3>Существующие промокоды</h3>${promos.map(p=>`<div class="admin-content-row"><div class="grow"><b>${esc(p.code)}</b><small>${p.reward==='sc'?`${p.amount} SC`:p.reward==='xp'?`${p.amount} XP`:`Кейс ${esc(p.caseName||'')}`} · использовано ${p.uses}/${p.limit} · ${p.active?'активен':'отключён'}</small></div><button class="ghost" onclick="adminTogglePromo('${p.id}')">${p.active?'Отключить':'Включить'}</button><button class="danger" onclick="adminDeletePromo('${p.id}')">Удалить</button></div>`).join('')||'<p class="muted">Промокодов пока нет.</p>'}</section>`}
function promoRewardChanged(){const reward=$('#promoReward')?.value;$('#promoAmountWrap').style.display=reward==='case'?'none':'';$('#promoCaseWrap').style.display=reward==='case'?'':'none'}
async function adminCreatePromo(){const body={code:$('#promoCode')?.value,reward:$('#promoReward')?.value,amount:Number($('#promoAmount')?.value),caseName:$('#promoCase')?.value,limit:Number($('#promoLimit')?.value)};try{await adminFetch('/api/admin/promocodes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('Промокод создан');renderAdminTab('promocodes')}catch(e){toast(e.message)}}
async function adminTogglePromo(id){try{await adminFetch('/api/admin/promocodes/'+id+'/toggle',{method:'POST'});renderAdminTab('promocodes')}catch(e){toast(e.message)}}
async function adminDeletePromo(id){if(!confirm('Удалить промокод?'))return;try{await adminFetch('/api/admin/promocodes/'+id,{method:'DELETE'});renderAdminTab('promocodes')}catch(e){toast(e.message)}}
async function adminPlayer(id){const d=await adminFetch('/api/admin/users/'+id);const u=d.user,muted=Number(u.mutedUntil)>Date.now();const modal=document.createElement('div');modal.className='case-overlay';modal.innerHTML=`<div class="case-result admin-modal"><div class="section-head"><div><div class="eyebrow">PLAYER</div><h2>${esc(u.login)}</h2></div><button class="ghost" onclick="this.closest('.case-overlay').remove()">Закрыть</button></div><div class="admin-metrics compact"><div class="metric"><span>Баланс</span><b>${Number(u.balance).toLocaleString()}</b></div><div class="metric"><span>Уровень</span><b>${u.level}</b></div><div class="metric"><span>Игры</span><b>${u.stats?.games||0}</b></div><div class="metric"><span>2FA</span><b>${u.twoFactor?'ON':'OFF'}</b></div></div><div class="admin-actions-grid"><div><h3>Баланс</h3><input id="admAmount" class="field" type="number" placeholder="+ / - SC"><input id="admReason" class="field" placeholder="Причина"><button class="accent wide" onclick="adminAdjust('${u.id}')">Применить</button></div><div><h3>Доступ</h3><p class="muted">Активных сессий: ${d.sessions.length}</p><button class="ghost wide" onclick="adminKick('${u.id}')">Кикнуть (завершить сессии)</button>${u.banned?`<button class="ghost wide" onclick="adminUnban('${u.id}');this.closest('.case-overlay').remove()">Разбанить</button>`:`<button class="danger wide" onclick="adminBan('${u.id}','${esc(u.login)}');this.closest('.case-overlay').remove()">Заблокировать</button>`}</div></div><div class="admin-mute"><h3>Мут в чате</h3><p class="muted">${muted?`Активен до ${new Date(u.mutedUntil).toLocaleString('ru-RU')}${u.muteReason?' · '+esc(u.muteReason):''}`:'Ограничений нет'}</p><input id="admMuteReason" class="field" maxlength="120" placeholder="Причина мута (необязательно)"><div class="admin-mute-btns">${[[10,'10 мин'],[60,'1 час'],[1440,'24 часа'],[10080,'7 дней']].map(x=>`<button class="ghost" onclick="adminMute('${u.id}',${x[0]})">${x[1]}</button>`).join('')}${muted?`<button class="accent" onclick="adminUnmute('${u.id}')">Снять мут</button>`:''}</div></div><h3>Последние операции</h3><div class="feed">${d.transactions.slice(0,12).map(t=>`<div class="row"><b class="${t.delta>=0?'positive':'negative'}">${t.delta>=0?'+':''}${t.delta} SC</b><span>${esc(t.type)} · ${new Date(t.at).toLocaleString()}</span></div>`).join('')||'<p class="muted">Нет операций.</p>'}</div></div>`;document.body.append(modal)}
async function adminMute(id,minutes){const reason=$('#admMuteReason')?.value.trim()||'';try{await adminFetch('/api/admin/users/'+id+'/mute',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({minutes,reason})});toast('Мут выдан');document.querySelector('.case-overlay')?.remove();adminPlayer(id)}catch(e){toast(e.message)}}
async function adminUnmute(id,from){try{await adminFetch('/api/admin/users/'+id+'/unmute',{method:'POST'});toast('Мут снят');if(from==='mod')renderAdminTab('moderation');else{document.querySelector('.case-overlay')?.remove();adminPlayer(id)}}catch(e){toast(e.message)}}
async function adminKick(id){const reason=prompt('Причина кика (необязательно)','');if(reason===null)return;try{const d=await adminFetch('/api/admin/users/'+id+'/kick',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});toast(`Игрок выброшен, сессий: ${d.sessions}`);document.querySelector('.case-overlay')?.remove()}catch(e){toast(e.message)}}
async function adminAdjust(id){const amount=Math.trunc(Number($('#admAmount')?.value)),reason=$('#admReason')?.value.trim();if(!amount||!reason)return toast('Укажи сумму и причину');try{await adminFetch('/api/admin/users/'+id+'/balance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount,reason})});toast('Баланс изменён');document.querySelector('.case-overlay')?.remove();await renderAdminTab('players')}catch(e){toast(e.message)}}
async function adminForceLogout(id){try{const d=await adminFetch('/api/admin/users/'+id+'/logout',{method:'POST'});toast(`Завершено сессий: ${d.sessions}`);document.querySelector('.case-overlay')?.remove()}catch(e){toast(e.message)}}
async function adminEconomy(){const d=await adminFetch('/api/admin/transactions?limit=100');const total=d.transactions.reduce((n,t)=>n+Math.abs(Number(t.delta)||0),0);return `<div class="admin-head"><div><div class="eyebrow">ECONOMY</div><h1>Экономика</h1><p class="muted">Все движения SC и ручные корректировки.</p></div><button class="ghost ap-csv" onclick="adminExport('transactions')">${apI('download',14)} CSV</button></div><div class="admin-metrics"><div class="metric"><span>Операций</span><b>${d.transactions.length}</b></div><div class="metric"><span>Объём</span><b>${total.toLocaleString()}</b><small>SC</small></div></div><section class="card"><div class="admin-table"><div class="admin-tr admin-th"><span>Игрок</span><span>Изменение</span><span>Тип</span><span>Дата</span></div>${d.transactions.map(t=>`<div class="admin-tr"><span><b>${esc(t.login)}</b></span><span class="${t.delta>=0?'positive':'negative'}">${t.delta>=0?'+':''}${t.delta} SC</span><span>${esc(t.type)}</span><span>${new Date(t.at).toLocaleString()}</span></div>`).join('')}</div></section>`}
async function adminContent(){const d=await adminFetch('/api/admin/content');return `<div class="admin-head"><div><div class="eyebrow">CONTENT</div><h1>Контент</h1><p class="muted">Социальная лента и игровой чат.</p></div></div><section class="card"><div class="section-head"><h3>Сообщение всем игрокам</h3></div><textarea id="adminBroadcast" class="field" rows="3" placeholder="Текст объявления"></textarea><button class="accent" onclick="adminBroadcast()">Опубликовать в системном чате</button></section><div class="admin-grid-2"><section class="card"><div class="section-head"><h3>Посты</h3></div>${d.posts.map(p=>`<div class="admin-content-row"><div><b>${esc(p.login)}</b><small>${new Date(p.at).toLocaleString()} · ♥ ${p.likes}</small><p>${esc(p.text)}</p></div><button class="danger" onclick="adminDeletePost('${p.id}')">Удалить</button></div>`).join('')||'<p class="muted">Постов нет.</p>'}</section><section class="card"><div class="section-head"><h3>Чат</h3></div>${d.chat.map(m=>`<div class="admin-content-row"><div><b>${esc(m.login||'SICO')}</b><small>${new Date(m.at).toLocaleString()}</small><p>${esc(m.text)}</p></div>${m.id?`<button class="danger" onclick="adminDeleteChat('${m.id}')">Удалить</button>`:''}</div>`).join('')||'<p class="muted">Сообщений нет.</p>'}</section></div>`}
async function adminBroadcast(){const text=$('#adminBroadcast')?.value.trim();if(!text)return toast('Текст пустой');try{await adminFetch('/api/admin/broadcast',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})});toast('Объявление отправлено');renderAdminTab('content')}catch(e){toast(e.message)}}
async function adminDeletePost(id){if(!confirm('Удалить пост?'))return;try{await adminFetch('/api/admin/posts/'+id,{method:'DELETE'});renderAdminTab('content')}catch(e){toast(e.message)}}
async function adminDeleteChat(id){if(!confirm('Удалить сообщение?'))return;try{await adminFetch('/api/admin/chat/'+id,{method:'DELETE'});renderAdminTab('content')}catch(e){toast(e.message)}}
async function adminModeration(){const users=await apAllUsers();const banned=users.filter(u=>u.banned),muted=users.filter(u=>Number(u.mutedUntil)>Date.now());return `<div class="admin-head"><div><div class="eyebrow">MODERATION</div><h1>Модерация</h1><p class="muted">Блокировки, муты и быстрые действия.</p></div></div><div class="admin-grid-2"><section class="card"><div class="section-head"><h3>Заблокированные игроки</h3><span class="muted">${banned.length}</span></div>${banned.map(u=>`<div class="person"><div class="grow"><b>${esc(u.login)}</b><small>${esc(u.banReason||'Причина не указана')}</small></div><button class="ghost" onclick="adminUnban('${u.id}').then(()=>renderAdminTab('moderation'))">Разбан</button></div>`).join('')||'<p class="muted">Заблокированных игроков нет.</p>'}</section><section class="card"><div class="section-head"><h3>Игроки в муте</h3><span class="muted">${muted.length}</span></div>${muted.map(u=>`<div class="person"><div class="grow"><b>${esc(u.login)}</b><small>до ${new Date(u.mutedUntil).toLocaleString('ru-RU')}</small></div><button class="ghost" onclick="adminUnmute('${u.id}','mod')">Снять мут</button></div>`).join('')||'<p class="muted">Сейчас никто не в муте.</p>'}</section></div><section class="card"><h3>Правила модерации</h3><p class="muted">Перед ручной корректировкой баланса всегда указывай понятную причину. Мут запрещает писать в общий чат, кик завершает сессии игрока (он может войти снова). Все действия сохраняются в журнале.</p></section>`}
const AP_LOG_LABELS={ban_user:['Бан','r'],unban_user:['Разбан','g'],mute_user:['Мут','o'],unmute_user:['Снятие мута','g'],kick_user:['Кик','r'],force_logout:['Завершение сессий','r'],balance_adjust:['Изменение баланса','b'],broadcast:['Объявление','b'],delete_chat:['Удаление сообщения','r'],delete_post:['Удаление поста','r'],delete_user:['Удаление игрока','r'],promo_create:['Промокод создан','g'],promo_delete:['Промокод удалён','r'],promo_toggle:['Промокод вкл/выкл','b'],promo_redeem:['Промокод активирован','g'],create_event:['Ивент создан','g'],delete_event:['Ивент удалён','r'],toggle_event:['Ивент вкл/выкл','b'],resolve_report:['Жалоба закрыта','g']};
const apLogLabel=a=>(AP_LOG_LABELS[a]||[a,'b'])[0];
const apLogText=l=>{const d=l.details||{};return typeof d==='object'?Object.entries(d).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`).join(' · '):String(d)};
async function adminLogs(){const d=await adminFetch('/api/admin/logs');window.__apLogs=d.logs||[];const acts=[...new Set(window.__apLogs.map(l=>l.action))].sort((a,b)=>apLogLabel(a).localeCompare(apLogLabel(b),'ru'));setTimeout(apLogsRender,0);return `<div class="admin-head"><div><div class="eyebrow">AUDIT LOG</div><h1>Журнал</h1><p class="muted">История административных действий. Хранятся последние 500 записей.</p></div><button class="ghost ap-csv" onclick="apLogsExport()">${apI('download',14)} CSV</button></div><section class="card"><div class="ap-filters"><input id="logQ" class="field" placeholder="Поиск: игрок, причина, код…" oninput="apLogsRender()"><select id="logAct" class="field" onchange="apLogsRender()"><option value="">Все действия</option>${acts.map(a=>`<option value="${esc(a)}">${esc(apLogLabel(a))}</option>`).join('')}</select><select id="logPer" class="field" onchange="apLogsRender()"><option value="0">За всё время</option><option value="1">24 часа</option><option value="7">7 дней</option><option value="30">30 дней</option></select></div><div class="ap-log-count" id="logCount"></div><div id="apLogRows"></div></section>`}
function apLogsRender(){const box=$('#apLogRows');if(!box)return;const q=($('#logQ')?.value||'').trim().toLowerCase(),act=$('#logAct')?.value||'',per=Number($('#logPer')?.value||0),since=per?Date.now()-per*86400000:0;const rows=(window.__apLogs||[]).filter(l=>(!act||l.action===act)&&(!since||(l.at||0)>=since)&&(!q||(apLogLabel(l.action)+' '+l.action+' '+apLogText(l)).toLowerCase().includes(q)));window.__apLogsShown=rows;const c=$('#logCount');if(c)c.textContent=`Показано ${rows.length} из ${(window.__apLogs||[]).length}`;box.innerHTML=rows.map(l=>{const t=(AP_LOG_LABELS[l.action]||[0,'b'])[1];return `<div class="ap-log"><time>${apTime(l.at)}</time><span class="ap-tag t-${t}">${esc(apLogLabel(l.action))}</span><span class="ap-log-d">${esc(apLogText(l))||'—'}</span></div>`}).join('')||'<p class="muted" style="padding:18px 0">Ничего не найдено.</p>'}
function apCsvText(rows){return '\ufeff'+rows.map(r=>r.map(v=>{let s=v==null?'':typeof v==='object'?JSON.stringify(v):String(v);if(typeof v==='string'&&/^[=+\-@\t\r]/.test(s))s="'"+s;return /[";\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(';')).join('\r\n')}
function apDownload(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function apLogsExport(){const rows=window.__apLogsShown||[];if(!rows.length)return toast('Нечего выгружать');apDownload(new Blob([apCsvText([['at','action','label','details'],...rows.map(l=>[new Date(l.at).toISOString(),l.action,apLogLabel(l.action),apLogText(l)])])],{type:'text/csv;charset=utf-8'}),`sico-admin-log-${new Date().toISOString().slice(0,10)}.csv`);toast(`Выгружено записей: ${rows.length}`)}
async function adminExport(what){try{const r=await fetch('/api/admin/export/'+what,{headers:adminHeaders()});if(!r.ok){let m='Не удалось выгрузить';try{m=(await r.json()).error||m}catch{}throw Error(m)}apDownload(await r.blob(),`sico-${what}-${new Date().toISOString().slice(0,10)}.csv`);toast('Файл скачан')}catch(e){toast(e.message)}}
async function adminLive(){const d=await adminFetch('/api/admin/live');return `<div class="admin-head"><div><div class="eyebrow">LIVE MONITOR</div><h1>Активность в реальном времени</h1><p class="muted">Сессии, сообщения и последние операции.</p></div><button class="ghost" onclick="renderAdminTab('live')">↻ Обновить</button></div><div class="admin-metrics"><div class="metric"><span>Активные сессии</span><b>${d.active.length}</b></div><div class="metric"><span>Всего сессий</span><b>${d.totalSessions}</b></div><div class="metric"><span>Сообщения в ленте</span><b>${d.recentChat.length}</b></div><div class="metric"><span>Последние операции</span><b>${d.recentTransactions.length}</b></div></div><div class="admin-grid-2"><section class="card"><h3>Активные игроки</h3>${d.active.map(x=>`<div class="admin-content-row"><div><b>${esc(x.user.login)}</b><small>Последняя активность: ${new Date(x.lastSeen).toLocaleTimeString()}</small></div><button class="ghost" onclick="adminPlayer('${x.user.id}')">Профиль</button></div>`).join('')||'<p class="muted">Нет активных сессий.</p>'}</section><section class="card"><h3>Последние сообщения чата</h3>${d.recentChat.map(m=>`<div class="admin-activity"><span class="activity-dot"></span><div><b>${esc(m.login||'SICO')}</b><p>${esc(m.text||'')}</p><small>${new Date(m.at||Date.now()).toLocaleString()}</small></div></div>`).join('')||'<p class="muted">Нет сообщений.</p>'}</section></div><section class="card"><h3>Последние операции</h3>${d.recentTransactions.map(t=>`<div class="admin-content-row"><div><b>${esc(t.login||'Игрок')}</b><small>${esc(t.type||'Операция')} · ${new Date(t.at||Date.now()).toLocaleString()}</small></div><strong>${Number(t.delta)>=0?'+':''}${Number(t.delta)||0} SC</strong></div>`).join('')||'<p class="muted">Нет операций.</p>'}</section>`}
async function adminReports(){const d=await adminFetch('/api/admin/reports');const all=d.reports||[],f=window.__apRepF||'open',open=all.filter(r=>r.status!=='resolved'),list=f==='all'?all:open;return `<div class="admin-head"><div><div class="eyebrow">TRUST & SAFETY</div><h1>Центр жалоб</h1><p class="muted">Жалобы игроков на сообщения и профили.</p></div><div class="ap-head-actions"><button class="ghost ap-csv" onclick="adminExport('reports')">${apI('download',14)} CSV</button><button class="ghost" onclick="renderAdminTab('reports')">↻ Обновить</button></div></div><section class="card"><div class="section-head"><h3>Жалобы</h3><div class="ap-seg"><button class="${f==='open'?'on':''}" onclick="adminRepFilter('open')">Открытые · ${open.length}</button><button class="${f==='all'?'on':''}" onclick="adminRepFilter('all')">Все · ${all.length}</button></div></div>${list.map(r=>`<div class="admin-content-row"><div class="grow"><b>${esc(r.reason||r.subject||r.type||'Жалоба')}</b>${r.targetLogin?` · на <b>${esc(r.targetLogin)}</b>`:''}<small>От: ${esc(r.reporterLogin||r.reporter||'неизвестно')} · ${new Date(r.at||r.createdAt||Date.now()).toLocaleString('ru-RU')} · ${r.status==='resolved'?'закрыта':'открыта'}</small>${r.messageText?`<blockquote class="ap-quote">${esc(r.messageText)}</blockquote>`:''}${r.text||r.reason&&!r.targetLogin?`<p>${esc(r.text||r.reason||'')}</p>`:''}${r.resolution?`<small>Решение: ${esc(r.resolution)}</small>`:''}</div>${r.targetId?`<button class="ghost" onclick="adminPlayer('${r.targetId}')">Профиль</button>`:''}${r.status!=='resolved'?`<button class="accent" onclick="adminResolveReport('${r.id}')">Рассмотрено</button>`:'<span class="badge-ok">Закрыта</span>'}</div>`).join('')||`<p class="muted">${f==='open'?'Открытых жалоб нет.':'Жалоб пока нет.'}</p>`}</section>`}
