async function adminEvents(){const d=await adminFetch('/api/admin/events');return `<div class="admin-head"><div><div class="eyebrow">EVENT STUDIO</div><h1>Ивенты</h1><p class="muted">Создавай временные события и показывай их статус в панели.</p></div></div><section class="card"><h3>Создать событие</h3><div class="admin-grid-2"><div><label>Название</label><input id="eventTitle" class="field" maxlength="100" placeholder="Например, Выходные XP"></div><div><label>Описание</label><input id="eventDescription" class="field" maxlength="500" placeholder="Кратко о событии"></div><div><label>Начало</label><input id="eventStart" class="field" type="datetime-local"></div><div><label>Окончание</label><input id="eventEnd" class="field" type="datetime-local"></div></div><button class="accent" onclick="adminCreateEvent()">Создать событие</button></section><section class="card"><h3>События</h3>${d.events.map(e=>`<div class="admin-content-row"><div class="grow"><b>${esc(e.title)}</b><small>${new Date(e.startAt).toLocaleString()} — ${new Date(e.endAt).toLocaleString()} · ${e.active?'включено':'отключено'}</small><p>${esc(e.description||'')}</p></div><button class="ghost" onclick="adminToggleEvent('${e.id}')">${e.active?'Отключить':'Включить'}</button><button class="danger" onclick="adminDeleteEvent('${e.id}')">Удалить</button></div>`).join('')||'<p class="muted">Событий пока нет.</p>'}</section>`}
async function adminCreateEvent(){const title=$('#eventTitle')?.value.trim(),description=$('#eventDescription')?.value.trim(),startAt=$('#eventStart')?.value?new Date($('#eventStart').value).getTime():Date.now(),endAt=$('#eventEnd')?.value?new Date($('#eventEnd').value).getTime():startAt+3600000;try{await adminFetch('/api/admin/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,description,startAt,endAt})});toast('Событие создано');renderAdminTab('events')}catch(e){toast(e.message)}}
