async function adminDiagnostics(){const d=await adminFetch('/api/admin/diagnostics');const mb=n=>(Number(n||0)/1024/1024).toFixed(1)+' MB';return `<div class="admin-head"><div><div class="eyebrow">SYSTEM HEALTH</div><h1>Диагностика</h1><p class="muted">Техническое состояние сервера и базы данных.</p></div><button class="ghost" onclick="renderAdminTab('diagnostics')">↻ Проверить снова</button></div><div class="admin-metrics"><div class="metric"><span>Время работы</span><b>${Math.floor(d.uptime/3600)}ч ${Math.floor(d.uptime%3600/60)}м</b></div><div class="metric"><span>Node.js</span><b>${esc(d.node)}</b></div><div class="metric"><span>Память процесса</span><b>${mb(d.memory.rss)}</b><small>RSS</small></div><div class="metric"><span>Heap</span><b>${mb(d.memory.heapUsed)}</b><small>из ${mb(d.memory.heapTotal)}</small></div></div><section class="card"><h3>Проверки системы</h3>${Object.entries(d.checks).map(([k,v])=>`<div class="admin-content-row"><span>${({database:'База данных',adminKey:'Ключ администратора',storage:'Хранилище данных'})[k]||k}</span><span class="${v?'badge-ok':'badge-danger'}">${v?'OK':'Ошибка'}</span></div>`).join('')}</section><section class="card"><h3>Размеры данных</h3>${Object.entries(d.database).map(([k,v])=>`<div class="admin-content-row"><span>${({users:'Пользователи',chat:'Сообщения чата',transactions:'Операции',posts:'Посты',logs:'Записи журнала'})[k]||k}</span><b>${Number(v).toLocaleString()}</b></div>`).join('')}<small class="muted">Проверка сделана ${new Date(d.timestamp).toLocaleString()}</small></section>`}
async function adminSettings(){return `<div class="admin-head"><div><div class="eyebrow">SYSTEM</div><h1>Система</h1><p class="muted">Системная информация и безопасный доступ.</p></div></div><section class="card"><h3>Доступ администратора</h3><p class="muted">Текущий вход использует серверный admin key из <code>data/admin.key</code>. Не публикуй этот файл и не добавляй его в Git.</p><div class="admin-notice">Для production лучше перенести админский доступ на отдельный аккаунт + 2FA и ограничить доступ к Admin Center по сети.</div></section><section class="card"><h3>Что контролирует Admin Center</h3><div class="row"><b>Игроки</b><span>профили, бан, сессии, баланс</span></div><div class="row"><b>Экономика</b><span>транзакции и ручные корректировки</span></div><div class="row"><b>Контент</b><span>посты, чат, объявления</span></div><div class="row"><b>Audit Log</b><span>административные действия</span></div></section>`}
async function adminBan(id,login){const opts=['Нарушение правил сообщества','Баг/эксплойт','Спам/флуд','Оскорбления в чате','Другое'];const reason=prompt(`Причина бана игрока ${login}:\n\n1 — нарушение правил\n2 — баг/эксплойт\n3 — спам/флуд\n4 — оскорбления\n5 — другое`,'1');const r=opts[(Number(reason)||1)-1]||opts[0];if(!confirm(`Заблокировать ${login}?\nПричина: ${r}`))return;try{await adminFetch('/api/admin/users/'+id+'/ban',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:r})});adminLogClient('ban');toast('Игрок заблокирован')}catch(e){toast(e.message)}}
