function adminLoginView(){document.body.dataset.route='admin';app.innerHTML=`<div class="ap-wrap"><div class="ap-login"><div class="ap-login-head"><div class="ap-logo">${apI('shield',20)}</div><div class="ap-title"><b>Admin Panel</b><span>Вход администратора</span></div></div><p class="muted">Используй серверный admin key. Он хранится в <code>data/admin.key</code>.</p><input id="adminLogin" class="field" placeholder="Логин" value="admin"><input id="adminKey" class="field" type="password" placeholder="Ключ администратора" onkeydown="if(event.key==='Enter')adminLogin()"><button class="accent wide" onclick="adminLogin()">Войти</button><button class="ghost wide" onclick="render('home')">Назад</button></div></div>`}
async function adminLogin(){try{const d=await api('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login:$('#adminLogin').value,key:$('#adminKey').value})});adminToken=d.token;localStorage.setItem('sico_admin_token',adminToken);render('admin');toast('Админ-доступ активирован')}catch(e){toast(e.message)}}
async function adminLogout(){await fetch('/api/admin/logout',{method:'POST',headers:adminHeaders()}).catch(()=>{});adminToken=null;localStorage.removeItem('sico_admin_token');render('home')}
function askSico(topic){const a={crash:'Crash работает непрерывно на сервере. Ставка списывается до раунда, а забрать можно только пока раунд идёт.',cases:'В кейсах награда выбирается сервером. Браузер не может задать себе нужную сумму.',loan:'Займ сначала приходит получателю как запрос. После подтверждения он получает SC, а вернуть нужно сумму +50%. Долг хранится отдельно.',safety:'Баланс, RNG и выплаты проверяются сервером. Для запросов изменения состояния используется одноразовый X-Request-ID.'};const el=$("#assistantAnswer");if(el)el.textContent=a[topic]||'SICO работает локально в твоей Wi‑Fi сети.'}
function updateChatCooldown(){const btn=$("#chatSendBtn"),input=$("#chatInput");if(!btn)return;const left=Math.max(0,chatSendUntil-Date.now());if(left<=0){btn.disabled=false;if(input)input.disabled=false;btn.textContent="→";if(chatTimer){clearInterval(chatTimer);chatTimer=null}return}btn.disabled=true;input&&(input.disabled=true);btn.textContent=`${Math.ceil(left/1000)}с`;if(!chatTimer)chatTimer=setInterval(updateChatCooldown,250)}
async function sendChat(){const i=$("#chatInput"),btn=$("#chatSendBtn"),text=i?.value.trim();if(!text)return;if(Date.now()<chatSendUntil){updateChatCooldown();return}try{await api("/api/chat",{method:"POST",headers:{"Content-Type":"application/json","X-Request-ID":rid()},body:JSON.stringify({text})});i.value="";chatSendUntil=Date.now()+5000;if(i)i.disabled=true;updateChatCooldown()}catch(e){toast(e.message);updateChatCooldown()}}
async function logout(){await api("/api/logout",{method:"POST"}).catch(()=>{});token=null;me=null;localStorage.removeItem("sico_token");if(socket){try{socket.close()}catch{}}authView()}
async function deleteAccount(){if(!confirm("Удалить аккаунт и его локальные данные?"))return;await api("/api/account",{method:"DELETE"});logout()}
async function refresh(){try{me=(await api("/api/me")).user;return true}catch(e){if(e.status===401){token=null;try{localStorage.removeItem("sico_token")}catch{}me=null;if(socket){try{socket.close()}catch{}socket=null}authView()}return false}}
function socketAuth(){if(socket&&socket.readyState===1&&token)socket.send(JSON.stringify({type:"auth",token,device}))}
function updateHomeLive(){
  if(route!=='home')return;
  const gameStrong=document.querySelector('.game strong');
  if(gameStrong&&state.crash)gameStrong.textContent=Number(state.crash.multiplier||1).toFixed(2)+'x';
  const round=document.querySelector('.metric-crash-round');
  if(round&&state.crash){round.querySelector('b')?.replaceChildren(document.createTextNode('#'+(state.crash.round||'—')));round.querySelector('small')?.replaceChildren(document.createTextNode(Number(state.crash.multiplier||1).toFixed(2)+'x сейчас'))}
}
function rouletteComputedAngle(el){try{const tr=getComputedStyle(el).transform;if(!tr||tr==='none')return 0;const m=new DOMMatrixReadOnly(tr);return Math.atan2(m.b,m.a)*180/Math.PI}catch{return 0}}
function updateRouletteDOM(r){
  if(route!=='roulette')return;
  if(r.state==='spinning'&&lastGameSound!==`spin-${r.round}`){lastGameSound=`spin-${r.round}`;sicoSound('spin')}
  if(r.state==='result'&&lastGameSound!==`result-${r.round}`){lastGameSound=`result-${r.round}`;sicoSound('win')}
  const wheel=document.querySelector('.roulette-wheel');
  if(wheel){
    if(r.state==='spinning'){
      wheel.classList.add('spinning');
      wheel.style.setProperty('--roulette-angle',wheel.style.getPropertyValue('--roulette-angle')||'0deg');
    }else if(r.state==='result'&&r.last){
      const current=rouletteComputedAngle(wheel),targetBase=rouletteTargetDeg(r.last.n);
      wheel.classList.remove('spinning');
      wheel.style.transition='none';
      wheel.style.setProperty('--roulette-angle',current+'deg');
      requestAnimationFrame(()=>{
        const normalized=((targetBase-current)%360+360)%360;
        const target=current+360*5+normalized;
        wheel.style.transition='transform 1.25s cubic-bezier(.12,.8,.16,1)';
        wheel.style.setProperty('--roulette-angle',target+'deg');
        wheel.dataset.angle=String(targetBase);
      });
    }
    const core=wheel.querySelector('.wheelcore');if(core)core.textContent=r.state==='spinning'?'…':r.last?r.last.n:'SICO';
  }
  const result=document.querySelector('.roulette-legend b');if(result)result.textContent=r.last?`${r.last.n} · ${r.last.color.toUpperCase()}`:'Ожидание';
  const bets=document.querySelector('#rouletteBets');if(bets)bets.innerHTML=(r.bets||[]).map(b=>`<div class="person"><div class="grow"><b>${esc(b.login)}</b><small>${b.choice}</small></div><b>${b.amount} SC</b></div>`).join('')||'<p class="muted">Стань первым.</p>';
  const status=document.querySelector('#rouletteStatus');if(status){status.className='status '+r.state;status.textContent=r.state==='open'?'● Ставки открыты':r.state==='spinning'?'Вращение…':'Результат'}
  const round=document.querySelector('#rouletteRound');if(round)round.textContent='ROUND #'+(r.round||'—');
}

function connect(){
  if(!token||socket&&(socket.readyState===0||socket.readyState===1))return;
  socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host);
  socket.onopen=()=>socketAuth();
  socket.onmessage=e=>{
    let m;try{m=JSON.parse(e.data)}catch{return}
    if(m.type==='state'){state={...state,...m.payload};if(route==='crash')updateCrashDOM(state.crash);else if(route==='roulette')updateRouletteDOM(state.roulette);else updateHomeLive();return}
    if(m.type==='crash'){if(m.payload.state==='crashed'&&lastGameSound!==`crash-${m.payload.round}`){lastGameSound=`crash-${m.payload.round}`;sicoSound('crash')}state.crash=m.payload;if(route==='crash')updateCrashDOM(m.payload);else updateHomeLive();return}
    if(m.type==='roulette'){state.roulette=m.payload;if(route==='roulette')updateRouletteDOM(m.payload);else updateHomeLive();return}
    if(m.type==='online'){state.online=m.payload.count;const o=document.querySelector('.online-pill');if(o)o.textContent='● '+state.online+' online';const metric=document.querySelector('.metric-online b');if(metric)metric.textContent=String(state.online);return}
    if(m.type==='loan'&&m.payload?.loan){const l=m.payload.loan;if(l.to===me?.id&&l.status==='pending')toast(`Новый запрос займа: ${l.principal} SC`);return}if(m.type==='chat'&&route==='extras'){const list=$("#chatList");if(list){list.insertAdjacentHTML('beforeend',chatMsg(m.payload));while(list.children.length>30)list.firstElementChild?.remove();list.scrollTop=list.scrollHeight}return}
    if(m.type==='market'){state.market=m.payload;if(route==='bank'&&window.bankTab==='trading'){const price=$('#scoinPrice');if(price)price.textContent=Number(m.payload.price).toFixed(4)+' SC';const chart=$('#scoinChart');if(chart)chart.innerHTML=tradingChart(m.payload.history);startMarketCountdown(m.payload.lastTick);}return}
    if(m.type==='wallet'&&me&&m.payload.userId===me.id){me.balance=m.payload.balance;me.level=m.payload.level;me.xp=m.payload.xp;const b=$(".balance");if(b&&!window.upgHold)b.textContent='◉ '+me.balance.toLocaleString()+' SC';const pb=document.querySelector('.profile-balance');if(pb)pb.textContent=me.balance+' SC'}
  };
  socket.onclose=()=>{const old=socket;socket=null;if(token)setTimeout(()=>{if(token&&!socket)connect()},1500);};
}
